const TOPICS={"A1.1":[{"t":"التعريف بالنفس","de":"Sich vorstellen","s":[["Hallo! Ich heiße Ahmed.","مرحبًا! اسمي أحمد."],["Ich bin 25 Jahre alt.","عمري 25 سنة."],["Ich komme aus Ägypten, aus Kairo.","أنا من مصر، من القاهرة."],["Jetzt wohne ich in Berlin.","أسكن الآن في برلين."],["Ich bin Student.","أنا طالب."],["Ich studiere Informatik.","أدرس علوم الحاسوب."],["Ich spreche Arabisch und Englisch.","أتكلم العربية والإنجليزية."],["Ich lerne jetzt Deutsch.","وأتعلم الألمانية الآن."],["Deutsch ist schwer, aber schön.","الألمانية صعبة، لكنها جميلة."],["Ich bin nicht verheiratet.","أنا غير متزوج."],["Mein Hobby ist Fußball.","هوايتي كرة القدم."],["Ich lese auch gern.","وأحب القراءة أيضًا."],["Meine Telefonnummer ist 0176 123 45 67.","رقم هاتفي 0176 123 45 67."],["Danke und auf Wiedersehen!","شكرًا، وإلى اللقاء!"]]},{"t":"عائلتي","de":"Meine Familie","s":[["Das ist meine Familie.","هذه عائلتي."],["Meine Familie ist groß.","عائلتي كبيرة."],["Mein Vater heißt Mahmoud.","اسم أبي محمود."],["Er ist 55 Jahre alt und arbeitet als Lehrer.","عمره 55 سنة، ويعمل معلّمًا."],["Meine Mutter heißt Fatma.","اسم أمي فاطمة."],["Sie ist Ärztin.","هي طبيبة."],["Ich habe einen Bruder und zwei Schwestern.","لدي أخ وأختان."],["Mein Bruder heißt Ali und ist 20.","اسم أخي علي، وعمره 20 سنة."],["Meine Schwestern sind noch klein.","أختاي ما زالتا صغيرتين."],["Sie gehen zur Schule.","تذهبان إلى المدرسة."],["Meine Großeltern wohnen auch bei uns.","جدي وجدتي يسكنان معنا أيضًا."],["Wir haben auch eine Katze.","ولدينا قطة أيضًا."],["Ich liebe meine Familie sehr.","أحب عائلتي كثيرًا."]]},{"t":"شقتي","de":"Meine Wohnung","s":[["Ich wohne in einer Wohnung in Köln.","أسكن في شقة في كولونيا."],["Die Wohnung ist nicht sehr groß.","الشقة ليست كبيرة جدًا."],["Sie hat zwei Zimmer, eine Küche und ein Bad.","فيها غرفتان ومطبخ وحمام."],["Das Wohnzimmer ist hell und schön.","غرفة المعيشة مضيئة وجميلة."],["Dort stehen ein Sofa, ein Tisch und ein Fernseher.","فيها أريكة وطاولة وتلفاز."],["Im Schlafzimmer habe ich ein Bett und einen Schrank.","في غرفة النوم عندي سرير وخزانة."],["Die Küche ist klein, aber modern.","المطبخ صغير لكنه حديث."],["Ich koche gern in meiner Küche.","أحب أن أطبخ في مطبخي."],["Die Wohnung hat auch einen Balkon.","في الشقة شرفة أيضًا."],["Die Miete ist 600 Euro.","الإيجار 600 يورو."],["Das ist nicht billig.","هذا ليس رخيصًا."],["Aber die Wohnung ist zentral.","لكن الشقة في موقع مركزي."],["Ich finde meine Wohnung super.","أرى أن شقتي رائعة."]]},{"t":"مدينتي","de":"Meine Stadt","s":[["Ich komme aus Alexandria.","أنا من الإسكندرية."],["Alexandria ist eine große Stadt in Ägypten.","الإسكندرية مدينة كبيرة في مصر."],["Die Stadt liegt am Meer.","تقع المدينة على البحر."],["Dort wohnen sehr viele Menschen.","يسكن فيها كثير جدًا من الناس."],["Es gibt viele Restaurants und Cafés.","فيها مطاعم ومقاهٍ كثيرة."],["Das Essen ist sehr gut.","الطعام لذيذ جدًا."],["Es gibt auch eine alte Bibliothek.","وفيها أيضًا مكتبة قديمة."],["Im Sommer ist es warm.","في الصيف يكون الطقس دافئًا."],["Viele Touristen kommen im Sommer.","يأتي سياح كثيرون في الصيف."],["Der Verkehr ist leider sehr laut.","المرور للأسف صاخب جدًا."],["Aber die Menschen sind freundlich.","لكن الناس لطفاء."],["Ich mag meine Stadt sehr.","أحب مدينتي كثيرًا."]]}],"A1.2":[{"t":"يومي","de":"Mein Tag","s":[["Ich stehe jeden Tag um sechs Uhr auf.","أستيقظ كل يوم في الساعة السادسة."],["Dann dusche ich.","ثم أستحم."],["Um halb sieben frühstücke ich.","في السادسة والنصف أتناول الفطور."],["Ich esse Brot mit Käse und trinke Tee.","آكل خبزًا بالجبن وأشرب الشاي."],["Um sieben Uhr fahre ich mit dem Bus zur Arbeit.","في السابعة أذهب إلى العمل بالحافلة."],["Ich arbeite von acht bis vier Uhr.","أعمل من الثامنة إلى الرابعة."],["Um zwölf mache ich Mittagspause.","في الثانية عشرة آخذ استراحة الغداء."],["Am Nachmittag kaufe ich ein.","بعد الظهر أشتري الحاجيات."],["Dann koche ich das Abendessen.","ثم أطبخ العشاء."],["Am Abend sehe ich fern oder lese.","في المساء أشاهد التلفاز أو أقرأ."],["Manchmal rufe ich meine Mutter an.","أحيانًا أتصل بأمي."],["Um elf Uhr gehe ich schlafen.","في الحادية عشرة أنام."],["Mein Tag ist lang, aber schön.","يومي طويل لكنه جميل."]]},{"t":"الطعام والشراب","de":"Essen und Trinken","s":[["Ich esse gern ägyptisches Essen.","أحب الطعام المصري."],["Mein Lieblingsessen ist Koshari.","أكلتي المفضلة الكشري."],["Zum Frühstück esse ich oft Ful und Eier.","في الفطور آكل الفول والبيض كثيرًا."],["Ich trinke morgens immer Tee.","في الصباح أشرب الشاي دائمًا."],["Kaffee trinke ich nicht so gern.","لا أحب القهوة كثيرًا."],["Mittags esse ich Reis mit Gemüse und Fleisch.","في الظهر آكل الأرز بالخضار واللحم."],["Ich esse kein Schweinefleisch.","لا آكل لحم الخنزير."],["Ich mag auch Obst, zum Beispiel Äpfel und Bananen.","أحب الفاكهة أيضًا، مثل التفاح والموز."],["Am Abend esse ich nicht viel.","في المساء لا آكل كثيرًا."],["Oft esse ich nur einen Salat.","كثيرًا ما آكل سلطة فقط."],["Am Wochenende gehe ich mit Freunden ins Restaurant.","في عطلة نهاية الأسبوع أذهب إلى مطعم مع أصدقائي."],["Ich trinke viel Wasser.","أشرب ماءً كثيرًا."],["Süßigkeiten esse ich nur manchmal.","آكل الحلويات أحيانًا فقط."]]},{"t":"التسوق","de":"Einkaufen","s":[["Am Samstag gehe ich einkaufen.","يوم السبت أذهب للتسوق."],["Ich gehe in den Supermarkt.","أذهب إلى السوبر ماركت."],["Ich brauche Brot, Milch und Eier.","أحتاج إلى خبز وحليب وبيض."],["Ich kaufe auch Obst und Gemüse.","وأشتري فاكهة وخضارًا أيضًا."],["Die Tomaten kosten zwei Euro.","الطماطم بيورويْن."],["Das ist ein bisschen teuer.","هذا غالٍ قليلًا."],["Ich nehme ein Kilo Kartoffeln.","آخذ كيلوغرامًا من البطاطس."],["Dann suche ich den Reis.","ثم أبحث عن الأرز."],["Ich frage eine Verkäuferin: Wo ist der Reis?","أسأل بائعة: أين الأرز؟"],["Sie sagt: Dort links, im Regal.","تقول: هناك على اليسار، في الرف."],["An der Kasse bezahle ich mit Karte.","عند الصندوق أدفع بالبطاقة."],["Alles kostet 35 Euro.","المجموع 35 يورو."],["Dann fahre ich nach Hause.","ثم أعود إلى البيت."]]},{"t":"وقت فراغي وعطلة نهاية الأسبوع","de":"Meine Freizeit","s":[["In meiner Freizeit mache ich gern Sport.","في وقت فراغي أحب ممارسة الرياضة."],["Ich spiele zweimal pro Woche Fußball.","ألعب كرة القدم مرتين في الأسبوع."],["Ich schwimme auch gern.","وأحب السباحة أيضًا."],["Am Wochenende habe ich viel Zeit.","في عطلة نهاية الأسبوع لدي وقت كثير."],["Am Samstag schlafe ich lange.","يوم السبت أنام طويلًا."],["Dann treffe ich meine Freunde.","ثم ألتقي بأصدقائي."],["Wir gehen ins Kino oder ins Café.","نذهب إلى السينما أو المقهى."],["Manchmal machen wir eine Party.","أحيانًا نقيم حفلة."],["Am Sonntag besuche ich meine Familie.","يوم الأحد أزور عائلتي."],["Wir essen zusammen und sprechen viel.","نأكل معًا ونتحدث كثيرًا."],["Am Abend lerne ich ein bisschen Deutsch.","في المساء أدرس الألمانية قليلًا."],["Ich höre auch gern Musik.","وأحب الاستماع إلى الموسيقى أيضًا."],["Das Wochenende ist immer zu kurz!","عطلة نهاية الأسبوع قصيرة جدًا دائمًا!"]]}],"A2.1":[{"t":"الإجازة الأخيرة","de":"Mein letzter Urlaub","s":[["Letzten Sommer habe ich Urlaub in Spanien gemacht.","في الصيف الماضي قضيت إجازة في إسبانيا."],["Ich bin mit meiner Familie nach Barcelona geflogen.","سافرت بالطائرة إلى برشلونة مع عائلتي."],["Der Flug hat drei Stunden gedauert.","استغرقت الرحلة ثلاث ساعات."],["Wir haben in einem Hotel am Meer gewohnt.","أقمنا في فندق على البحر."],["Das Hotel war klein, aber sehr sauber.","كان الفندق صغيرًا لكنه نظيف جدًا."],["Jeden Tag sind wir an den Strand gegangen.","كنا نذهب إلى الشاطئ كل يوم."],["Das Wetter war heiß und sonnig.","كان الطقس حارًا ومشمسًا."],["Wir haben viele Sehenswürdigkeiten besichtigt.","زرنا معالم سياحية كثيرة."],["Besonders die Kirche Sagrada Família hat mir gefallen.","أعجبتني كنيسة ساغرادا فاميليا بشكل خاص."],["Am Abend haben wir in Restaurants gegessen.","في المساء كنا نأكل في المطاعم."],["Das spanische Essen hat sehr gut geschmeckt.","كان طعم الطعام الإسباني لذيذًا جدًا."],["Ich habe auch ein paar Wörter Spanisch gelernt.","وتعلمت بعض الكلمات الإسبانية أيضًا."],["Nach zehn Tagen sind wir nach Hause zurückgeflogen.","بعد عشرة أيام عدنا إلى البيت بالطائرة."],["Es war ein wunderschöner Urlaub.","كانت إجازة رائعة."]]},{"t":"عند الطبيب","de":"Beim Arzt","s":[["Letzte Woche war ich krank.","في الأسبوع الماضي كنت مريضًا."],["Ich hatte Fieber und starke Kopfschmerzen.","كانت لدي حمّى وصداع شديد."],["Deshalb habe ich beim Arzt angerufen.","لذلك اتصلت بالطبيب."],["Ich habe einen Termin für Dienstag bekommen.","حصلت على موعد يوم الثلاثاء."],["Im Wartezimmer habe ich eine halbe Stunde gewartet.","انتظرت نصف ساعة في غرفة الانتظار."],["Dann hat mich der Arzt untersucht.","ثم فحصني الطبيب."],["Er hat gesagt: Sie haben eine Grippe.","قال: لديك إنفلونزا."],["Ich musste drei Tage im Bett bleiben.","كان عليّ أن أبقى في السرير ثلاثة أيام."],["Er hat mir ein Rezept gegeben.","أعطاني وصفة طبية."],["In der Apotheke habe ich Tabletten gekauft.","اشتريت أقراصًا من الصيدلية."],["Ich habe viel Tee getrunken und viel geschlafen.","شربت شايًا كثيرًا ونمت كثيرًا."],["Mein Chef hat eine Krankmeldung bekommen.","استلم مديري الشهادة المرضية."],["Jetzt bin ich wieder gesund.","الآن أصبحت بخير مرة أخرى."]]},{"t":"الطقس وفصول السنة","de":"Das Wetter und die Jahreszeiten","s":[["In Deutschland gibt es vier Jahreszeiten.","في ألمانيا أربعة فصول."],["Im Frühling wird es langsam wärmer.","في الربيع يدفأ الطقس شيئًا فشيئًا."],["Die Blumen blühen und die Tage werden länger.","تتفتح الأزهار ويطول النهار."],["Der Sommer ist meistens warm und schön.","الصيف غالبًا دافئ وجميل."],["Manchmal ist es aber auch sehr heiß.","لكنه يكون أحيانًا حارًا جدًا."],["Im Herbst regnet es oft und es ist windig.","في الخريف تمطر كثيرًا وتهب الرياح."],["Die Blätter werden gelb und rot.","تصبح أوراق الشجر صفراء وحمراء."],["Der Winter ist kalt und dunkel.","الشتاء بارد ومظلم."],["Manchmal schneit es.","أحيانًا تتساقط الثلوج."],["In Ägypten ist das Wetter ganz anders.","في مصر الطقس مختلف تمامًا."],["Dort ist es fast immer sonnig.","هناك تكون الشمس مشرقة دائمًا تقريبًا."],["Meine Lieblingsjahreszeit ist der Frühling.","فصلي المفضل هو الربيع."],["Dann ist es nicht zu kalt und nicht zu heiß.","حينها لا يكون الطقس باردًا جدًا ولا حارًا جدًا."]]},{"t":"الأعياد والاحتفالات","de":"Feste feiern","s":[["In meiner Familie feiern wir gern zusammen.","في عائلتي نحب أن نحتفل معًا."],["Das wichtigste Fest ist für uns das Zuckerfest.","أهم عيد عندنا عيد الفطر."],["Vorher fasten wir einen Monat lang im Ramadan.","قبله نصوم شهر رمضان."],["Am Festtag ziehen wir neue Kleidung an.","في يوم العيد نلبس ملابس جديدة."],["Wir besuchen unsere Verwandten.","نزور أقاربنا."],["Die Kinder bekommen Geld und Geschenke.","يحصل الأطفال على العيدية والهدايا."],["Meine Mutter backt immer Kekse.","أمي تصنع الكعك دائمًا."],["Letztes Jahr habe ich das Fest in Deutschland gefeiert.","في العام الماضي احتفلت بالعيد في ألمانيا."],["Ich habe meine Freunde zum Essen eingeladen.","دعوت أصدقائي إلى الطعام."],["Sie haben mir Blumen mitgebracht.","أحضروا لي الزهور."],["Meine deutschen Freunde feiern Weihnachten.","أصدقائي الألمان يحتفلون بعيد الميلاد."],["Im Dezember haben sie mich eingeladen.","في ديسمبر دعوني."],["Feste sind schön, weil die Familie zusammenkommt.","الأعياد جميلة لأن العائلة تجتمع."]]}],"A2.2":[{"t":"عملي","de":"Mein Beruf","s":[["Ich arbeite als Krankenpfleger in einem Krankenhaus.","أعمل ممرضًا في مستشفى."],["Ich arbeite dort seit drei Jahren.","أعمل هناك منذ ثلاث سنوات."],["Meine Arbeit ist interessant, aber anstrengend.","عملي ممتع لكنه متعب."],["Ich arbeite im Schichtdienst.","أعمل بنظام المناوبات."],["Manchmal muss ich auch nachts arbeiten.","أحيانًا يجب أن أعمل ليلًا أيضًا."],["Ich helfe den Patienten und gebe ihnen Medikamente.","أساعد المرضى وأعطيهم الأدوية."],["Meine Kollegen sind sehr nett.","زملائي لطفاء جدًا."],["Wir helfen uns immer gegenseitig.","نساعد بعضنا دائمًا."],["Mein Chef ist streng, aber fair.","مديري صارم لكنه عادل."],["Das Gehalt ist in Ordnung.","الراتب جيد."],["Ich mag meinen Beruf, weil ich Menschen helfen kann.","أحب عملي لأنني أستطيع مساعدة الناس."],["Später möchte ich eine Weiterbildung machen.","لاحقًا أريد أن أحصل على تدريب إضافي."],["Dann kann ich mehr verdienen.","حينها أستطيع أن أكسب أكثر."]]},{"t":"صديقي المقرّب","de":"Mein bester Freund","s":[["Mein bester Freund heißt Karim.","اسم صديقي المقرّب كريم."],["Wir kennen uns seit der Schule.","نعرف بعضنا منذ أيام المدرسة."],["Er ist groß, hat schwarze Haare und trägt eine Brille.","هو طويل، وشعره أسود، ويلبس نظارة."],["Karim ist sehr lustig und hilfsbereit.","كريم مرح جدًا ويحب المساعدة."],["Wenn ich ein Problem habe, rufe ich ihn an.","عندما تكون لدي مشكلة أتصل به."],["Er hört immer zu und gibt mir gute Tipps.","يستمع إليّ دائمًا ويعطيني نصائح جيدة."],["Wir haben die gleichen Hobbys.","لدينا الهوايات نفسها."],["Wir spielen zusammen Tennis und gehen ins Kino.","نلعب التنس معًا ونذهب إلى السينما."],["Manchmal streiten wir uns auch.","أحيانًا نتشاجر أيضًا."],["Aber danach versöhnen wir uns schnell.","لكننا نتصالح بسرعة بعد ذلك."],["Leider wohnt er jetzt in einer anderen Stadt.","للأسف يسكن الآن في مدينة أخرى."],["Wir telefonieren aber jede Woche.","لكننا نتحدث بالهاتف كل أسبوع."],["Ich bin froh, dass ich so einen Freund habe.","أنا سعيد لأن لدي صديقًا مثله."]]},{"t":"حماية البيئة في الحياة اليومية","de":"Umweltschutz im Alltag","s":[["Umweltschutz ist heute sehr wichtig.","حماية البيئة مهمة جدًا اليوم."],["Ich glaube, dass jeder etwas tun kann.","أعتقد أن كل شخص يستطيع أن يفعل شيئًا."],["Zu Hause trennen wir den Müll.","في البيت نفرز النفايات."],["Papier, Plastik und Glas kommen in verschiedene Tonnen.","يُرمى الورق والبلاستيك والزجاج في حاويات مختلفة."],["Ich fahre oft mit dem Fahrrad statt mit dem Auto.","كثيرًا ما أركب الدراجة بدلًا من السيارة."],["Beim Einkaufen nehme ich immer eine Stofftasche mit.","عندما أتسوق آخذ دائمًا حقيبة من القماش."],["So brauche ich keine Plastiktüten.","وهكذا لا أحتاج إلى أكياس بلاستيكية."],["Ich mache das Licht aus, wenn ich das Zimmer verlasse.","أطفئ الضوء عندما أغادر الغرفة."],["Ich dusche kurz, weil ich Wasser sparen will.","أستحم بسرعة لأنني أريد توفير الماء."],["Ich kaufe gern Obst und Gemüse aus der Region.","أحب شراء الفاكهة والخضار من المنطقة."],["Das ist gut für die Umwelt.","هذا جيد للبيئة."],["Es sind kleine Dinge, aber sie helfen.","إنها أشياء صغيرة لكنها تُحدث فرقًا."],["Wenn alle mitmachen, wird die Welt sauberer.","إذا شارك الجميع، سيصبح العالم أنظف."]]},{"t":"أيام دراستي","de":"Meine Schulzeit","s":[["Ich bin in Kairo zur Schule gegangen.","التحقت بالمدرسة في القاهرة."],["Die Grundschule war in der Nähe von unserem Haus.","كانت المدرسة الابتدائية قريبة من بيتنا."],["Ich bin jeden Tag zu Fuß gegangen.","كنت أذهب إليها كل يوم مشيًا."],["Mein Lieblingsfach war Mathematik.","كانت مادتي المفضلة الرياضيات."],["Sport mochte ich nicht so gern.","لم أكن أحب الرياضة كثيرًا."],["Meine Lehrerin in Englisch war sehr nett.","كانت معلّمة الإنجليزية لطيفة جدًا."],["Wir hatten jeden Tag viele Hausaufgaben.","كانت لدينا واجبات كثيرة كل يوم."],["In den Pausen haben wir im Hof gespielt.","في الاستراحة كنا نلعب في الساحة."],["Nach der Schule habe ich an der Universität studiert.","بعد المدرسة درست في الجامعة."],["Ich habe Wirtschaft studiert.","درست الاقتصاد."],["Das Studium hat vier Jahre gedauert.","استغرقت الدراسة أربع سنوات."],["Ich denke gern an meine Schulzeit zurück.","أحب أن أتذكر أيام المدرسة."],["Ich habe dort meine besten Freunde kennengelernt.","هناك تعرفت على أقرب أصدقائي."]]}],"B1.1":[{"t":"البحث عن شقة","de":"Wohnungssuche","s":[["Als ich nach Deutschland gekommen bin, musste ich zuerst eine Wohnung finden.","عندما جئت إلى ألمانيا، كان عليّ أولًا أن أجد شقة."],["Das war schwieriger, als ich gedacht hatte.","كان ذلك أصعب مما توقعت."],["In großen Städten gibt es nur wenige freie Wohnungen, und die Mieten sind hoch.","في المدن الكبيرة توجد شقق شاغرة قليلة، والإيجارات مرتفعة."],["Ich habe jeden Tag Anzeigen im Internet gelesen und viele Vermieter angeschrieben.","كنت أقرأ الإعلانات على الإنترنت كل يوم وأراسل كثيرًا من المؤجرين."],["Leider habe ich oft keine Antwort bekommen.","للأسف لم أتلقَّ ردًا في أغلب الأحيان."],["Zu einer Besichtigung kamen manchmal zwanzig Leute gleichzeitig.","أحيانًا كان يأتي عشرون شخصًا لمعاينة الشقة في الوقت نفسه."],["Die Vermieter wollten viele Unterlagen sehen, zum Beispiel einen Arbeitsvertrag und eine Schufa-Auskunft.","أراد المؤجرون رؤية مستندات كثيرة، مثل عقد العمل وشهادة السجل الائتماني."],["Nach zwei Monaten hatte ich endlich Glück.","بعد شهرين حالفني الحظ أخيرًا."],["Ein Kollege hat mir von einer Wohnung erzählt, die in seinem Haus frei geworden war.","أخبرني زميل عن شقة أصبحت شاغرة في مبناه."],["Die Wohnung ist nicht groß, aber hell und ruhig.","الشقة ليست كبيرة، لكنها مضيئة وهادئة."],["Die Nebenkosten sind schon in der Miete enthalten.","التكاليف الإضافية مشمولة في الإيجار."],["Ich habe den Mietvertrag sofort unterschrieben.","وقّعت عقد الإيجار فورًا."],["Heute bin ich sehr zufrieden, obwohl die Suche so anstrengend war.","اليوم أنا راضٍ جدًا، رغم أن البحث كان مرهقًا للغاية."]]},{"t":"تدريبي وخططي","de":"Meine Ausbildung und meine Pläne","s":[["Zurzeit mache ich eine Ausbildung als Elektriker.","حاليًا أتلقى تدريبًا مهنيًا لأصبح كهربائيًا."],["Die Ausbildung dauert dreieinhalb Jahre.","يستغرق التدريب ثلاث سنوات ونصفًا."],["Drei Tage pro Woche arbeite ich in einem Betrieb, zwei Tage gehe ich in die Berufsschule.","أعمل ثلاثة أيام في الأسبوع في شركة، وأذهب يومين إلى المدرسة المهنية."],["In der Berufsschule lernen wir die Theorie, im Betrieb die Praxis.","في المدرسة المهنية نتعلم الجانب النظري، وفي الشركة الجانب العملي."],["Am Anfang war die Fachsprache für mich sehr schwer.","في البداية كانت لغة المهنة صعبة جدًا عليّ."],["Deshalb habe ich zusätzlich einen Deutschkurs besucht.","لذلك حضرت دورة إضافية في اللغة الألمانية."],["Inzwischen verstehe ich fast alles.","الآن أصبحت أفهم كل شيء تقريبًا."],["Mein Meister ist zufrieden mit mir und erklärt mir viel.","معلّمي راضٍ عني ويشرح لي كثيرًا."],["Ich bekomme auch ein kleines Gehalt, was mir sehr hilft.","وأحصل أيضًا على راتب صغير، وهذا يساعدني كثيرًا."],["Nach der Prüfung möchte ich in der Firma bleiben.","بعد الامتحان أريد أن أبقى في الشركة."],["Später würde ich gern den Meister machen, damit ich mehr Verantwortung übernehmen kann.","لاحقًا أود أن أحصل على شهادة المعلّم الحرفي لأتحمل مسؤولية أكبر."],["Vielleicht eröffne ich irgendwann sogar eine eigene Firma.","ربما أفتح يومًا ما شركة خاصة بي."],["Ich bin froh, dass ich mich für diesen Weg entschieden habe.","أنا سعيد لأنني اخترت هذا الطريق."]]},{"t":"الصداقة","de":"Freundschaft","s":[["Für mich ist Freundschaft eines der wichtigsten Dinge im Leben.","الصداقة بالنسبة لي من أهم الأشياء في الحياة."],["Ein guter Freund ist jemand, auf den man sich immer verlassen kann.","الصديق الجيد هو من يمكنك الاعتماد عليه دائمًا."],["Er hört zu, wenn man Probleme hat, und sagt ehrlich seine Meinung.","يستمع إليك عندما تكون لديك مشكلات، ويقول رأيه بصراحة."],["Als ich neu in Deutschland war, hatte ich am Anfang keine Freunde.","عندما كنت جديدًا في ألمانيا، لم يكن لدي أصدقاء في البداية."],["Ich habe mich oft allein gefühlt.","كثيرًا ما شعرت بالوحدة."],["Dann habe ich mich in einem Sportverein angemeldet.","ثم اشتركت في نادٍ رياضي."],["Dort habe ich Menschen kennengelernt, die die gleichen Interessen haben wie ich.","هناك تعرفت على أشخاص لديهم اهتماماتي نفسها."],["Mit zwei von ihnen treffe ich mich jetzt regelmäßig.","الآن ألتقي باثنين منهم بانتظام."],["Wir kochen zusammen, gehen spazieren oder reden einfach stundenlang.","نطبخ معًا، أو نتمشى، أو نتحدث ساعات طويلة."],["Natürlich gibt es manchmal auch Missverständnisse.","بالطبع يحدث أحيانًا سوء تفاهم."],["Aber wir sprechen dann offen darüber und finden eine Lösung.","لكننا حينها نتحدث عنه بصراحة ونجد حلًا."],["Meine alten Freunde in Ägypten vermisse ich trotzdem sehr.","ومع ذلك أشتاق كثيرًا إلى أصدقائي القدامى في مصر."],["Zum Glück können wir jeden Tag schreiben und telefonieren.","لحسن الحظ نستطيع أن نتراسل ونتحدث كل يوم."]]},{"t":"الحياة في بلد جديد","de":"Leben in einem neuen Land","s":[["Vor zwei Jahren bin ich nach Deutschland gezogen.","انتقلت إلى ألمانيا قبل عامين."],["Am Anfang war vieles neu und fremd für mich.","في البداية كان كثير من الأشياء جديدًا وغريبًا عليّ."],["Ich musste viele Formulare ausfüllen und zu verschiedenen Ämtern gehen.","كان عليّ ملء استمارات كثيرة والذهاب إلى دوائر حكومية مختلفة."],["Besonders das Wetter war eine Umstellung, weil es im Winter so dunkel ist.","كان الطقس بالذات تغييرًا كبيرًا، لأن الشتاء مظلم جدًا."],["Auch das Essen schmeckt hier anders als zu Hause.","والطعام أيضًا مذاقه هنا مختلف عن بلدي."],["Ich habe aber schnell gemerkt, dass die Sprache der Schlüssel zu allem ist.","لكنني أدركت بسرعة أن اللغة هي مفتاح كل شيء."],["Deshalb habe ich jeden Tag Deutsch gelernt.","لذلك كنت أتعلم الألمانية كل يوم."],["Die Deutschen sind am Anfang oft etwas zurückhaltend.","الألمان غالبًا متحفظون قليلًا في البداية."],["Wenn man sie aber besser kennt, sind sie sehr hilfsbereit.","لكن عندما تعرفهم أكثر، يكونون مستعدين جدًا للمساعدة."],["Pünktlichkeit ist hier sehr wichtig, das habe ich schnell gelernt.","الالتزام بالمواعيد مهم جدًا هنا، وقد تعلمت ذلك بسرعة."],["Inzwischen habe ich eine Arbeit und eine eigene Wohnung.","الآن لدي عمل وشقة خاصة بي."],["Manchmal habe ich Heimweh, aber ich fühle mich hier immer mehr zu Hause.","أحيانًا أشتاق إلى وطني، لكنني أشعر هنا بأنني في بيتي أكثر فأكثر."],["Ich würde jedem raten, offen und geduldig zu sein.","أنصح الجميع بأن يكونوا منفتحين وصبورين."]]}],"B1.2":[{"t":"الإعلام في حياتي اليومية","de":"Medien in meinem Alltag","s":[["Medien spielen in meinem Alltag eine große Rolle.","للإعلام دور كبير في حياتي اليومية."],["Morgens lese ich die Nachrichten auf meinem Handy, während ich frühstücke.","في الصباح أقرأ الأخبار على هاتفي بينما أتناول الفطور."],["Zeitungen aus Papier kaufe ich fast nie.","نادرًا ما أشتري صحفًا ورقية."],["Im Bus höre ich oft Podcasts, um mein Deutsch zu verbessern.","في الحافلة كثيرًا ما أستمع إلى البودكاست لأحسّن لغتي الألمانية."],["Am Abend schaue ich manchmal eine Serie im Internet.","في المساء أشاهد أحيانًا مسلسلًا على الإنترنت."],["Fernsehen schaue ich dagegen nur selten.","أما التلفاز فنادرًا ما أشاهده."],["Soziale Netzwerke benutze ich vor allem, um mit meiner Familie in Kontakt zu bleiben.","أستخدم وسائل التواصل الاجتماعي أساسًا للبقاء على تواصل مع عائلتي."],["Allerdings verbringe ich manchmal zu viel Zeit am Handy.","لكنني أحيانًا أقضي وقتًا طويلًا جدًا على الهاتف."],["Deshalb habe ich mir vorgenommen, abends eine Stunde ohne Bildschirm zu verbringen.","لذلك قررت أن أقضي ساعة في المساء دون شاشات."],["Man muss auch vorsichtig sein, denn nicht alle Informationen im Internet sind richtig.","ويجب أن يكون المرء حذرًا، لأن ليست كل المعلومات على الإنترنت صحيحة."],["Ich vergleiche deshalb oft mehrere Quellen.","لذلك كثيرًا ما أقارن بين مصادر عدة."],["Ohne Medien könnte ich mir mein Leben kaum vorstellen.","لا أستطيع أن أتخيل حياتي دون إعلام."],["Trotzdem finde ich, dass man sie bewusst nutzen sollte.","ومع ذلك أرى أنه ينبغي استخدامه بوعي."]]},{"t":"الحياة الصحية","de":"Gesund leben","s":[["Seit einem Jahr versuche ich, gesünder zu leben.","منذ عام أحاول أن أعيش بطريقة صحية أكثر."],["Früher habe ich viel Fast Food gegessen und kaum Sport gemacht.","في السابق كنت آكل كثيرًا من الوجبات السريعة، ولا أمارس الرياضة تقريبًا."],["Ich war oft müde und hatte keine Energie.","كنت متعبًا كثيرًا ولا طاقة لدي."],["Mein Arzt hat mir geraten, meine Ernährung zu ändern.","نصحني طبيبي بأن أغيّر نظامي الغذائي."],["Jetzt koche ich meistens selbst und esse mehr Obst und Gemüse.","الآن أطبخ بنفسي غالبًا، وآكل فاكهة وخضارًا أكثر."],["Statt Limonade trinke ich Wasser oder Tee.","بدلًا من المشروبات الغازية أشرب الماء أو الشاي."],["Dreimal pro Woche gehe ich ins Fitnessstudio.","أذهب إلى النادي الرياضي ثلاث مرات في الأسبوع."],["Am Anfang war das sehr anstrengend, aber inzwischen macht es mir Spaß.","في البداية كان ذلك متعبًا جدًا، لكنني الآن أستمتع به."],["Außerdem fahre ich jetzt mit dem Fahrrad zur Arbeit.","وإضافة إلى ذلك أذهب الآن إلى العمل بالدراجة."],["Ich achte auch darauf, genug zu schlafen.","وأحرص أيضًا على أن أنام بما يكفي."],["Seitdem fühle ich mich viel besser und bin seltener krank.","منذ ذلك الحين أشعر بتحسن كبير، وأمرض أقل."],["Natürlich esse ich manchmal noch Schokolade.","بالطبع ما زلت آكل الشوكولاتة أحيانًا."],["Wichtig ist nicht, perfekt zu sein, sondern regelmäßig etwas für die Gesundheit zu tun.","المهم ليس أن تكون مثاليًا، بل أن تفعل شيئًا لصحتك بانتظام."]]},{"t":"تقديم شكوى","de":"Eine Beschwerde","s":[["Letzten Monat habe ich im Internet eine Waschmaschine bestellt.","في الشهر الماضي طلبت غسالة عبر الإنترنت."],["Laut Bestätigung sollte sie innerhalb von drei Tagen geliefert werden.","وفق التأكيد كان يجب أن تصل خلال ثلاثة أيام."],["Nach einer Woche war sie aber immer noch nicht da.","لكنها لم تكن قد وصلت بعد أسبوع."],["Ich habe deshalb beim Kundenservice angerufen.","لذلك اتصلت بخدمة العملاء."],["Ein Mitarbeiter hat mir versprochen, dass sie am nächsten Tag kommt.","وعدني موظف بأنها ستصل في اليوم التالي."],["Als sie endlich geliefert wurde, war das Gerät beschädigt.","وعندما وصلت أخيرًا، كان الجهاز تالفًا."],["Die Tür ließ sich nicht richtig schließen.","لم يكن الباب يُغلق بشكل صحيح."],["Ich habe sofort Fotos gemacht und eine Beschwerde geschrieben.","التقطت صورًا فورًا وكتبت شكوى."],["Darin habe ich das Problem genau beschrieben und um einen Ersatz gebeten.","وصفت فيها المشكلة بدقة وطلبت جهازًا بديلًا."],["Außerdem habe ich darauf hingewiesen, dass ich mir für die Lieferung zweimal freigenommen hatte.","وأشرت أيضًا إلى أنني أخذت إجازة من العمل مرتين من أجل التوصيل."],["Zwei Tage später kam eine freundliche Antwort.","بعد يومين وصلني رد لطيف."],["Die Firma hat mir eine neue Maschine geschickt und einen Gutschein über 50 Euro gegeben.","أرسلت لي الشركة غسالة جديدة وقسيمة بقيمة 50 يورو."],["Ich habe gelernt, dass es sich lohnt, sich höflich, aber deutlich zu beschweren.","تعلمت أن الشكوى المهذبة والواضحة تؤتي ثمارها."]]},{"t":"المدينة أم الريف؟","de":"Stadt oder Land?","s":[["Viele Menschen fragen sich, ob man besser in der Stadt oder auf dem Land wohnt.","يتساءل كثير من الناس: هل الأفضل أن نعيش في المدينة أم في الريف؟"],["Die Stadt hat viele Vorteile.","للمدينة مزايا كثيرة."],["Es gibt mehr Arbeitsplätze, Geschäfte, Kinos und Theater.","فيها فرص عمل أكثر، ومتاجر، ودور سينما، ومسارح."],["Außerdem sind die öffentlichen Verkehrsmittel meistens gut, sodass man kein Auto braucht.","كما أن المواصلات العامة جيدة غالبًا، فلا يحتاج المرء إلى سيارة."],["Allerdings ist das Leben in der Stadt oft laut und teuer.","لكن الحياة في المدينة غالبًا صاخبة ومكلفة."],["Die Mieten steigen ständig, und es gibt wenig Natur.","الإيجارات ترتفع باستمرار، والطبيعة قليلة."],["Auf dem Land ist es dagegen ruhig, und die Luft ist sauber.","أما في الريف فالحياة هادئة والهواء نقي."],["Kinder können draußen spielen, und die Häuser sind oft größer und billiger.","يستطيع الأطفال اللعب في الخارج، والبيوت غالبًا أكبر وأرخص."],["Ein Nachteil ist jedoch, dass man für fast alles ein Auto braucht.","لكن من العيوب أن المرء يحتاج إلى سيارة لكل شيء تقريبًا."],["Ärzte, Schulen und Supermärkte sind manchmal weit entfernt.","الأطباء والمدارس والمتاجر بعيدة أحيانًا."],["Ich persönlich wohne lieber in der Stadt, weil ich gern ausgehe.","أنا شخصيًا أفضّل العيش في المدينة لأنني أحب الخروج."],["Wenn ich aber Kinder habe, ziehe ich vielleicht aufs Land.","لكن إذا أصبح لدي أطفال، فربما أنتقل إلى الريف."],["Am Ende hängt die Entscheidung von der Lebenssituation ab.","في النهاية يعتمد القرار على ظروف الحياة."]]}],"B2.1":[{"t":"الرقمنة وعالم العمل","de":"Die Digitalisierung der Arbeitswelt","s":[["Die Digitalisierung hat die Arbeitswelt in den letzten Jahren grundlegend verändert.","غيّرت الرقمنة عالم العمل تغييرًا جذريًا في السنوات الأخيرة."],["Viele Aufgaben, die früher von Menschen erledigt wurden, werden heute von Computern übernommen.","كثير من المهام التي كان يؤديها البشر في الماضي تتولاها الحواسيب اليوم."],["Dadurch können Unternehmen schneller und günstiger produzieren.","وبذلك تستطيع الشركات أن تنتج أسرع وبتكلفة أقل."],["Gleichzeitig befürchten viele Beschäftigte, ihren Arbeitsplatz zu verlieren.","وفي الوقت نفسه يخشى كثير من العاملين فقدان وظائفهم."],["Diese Sorge ist zum Teil berechtigt, denn einfache Routinetätigkeiten werden zunehmend automatisiert.","وهذا القلق مبرر جزئيًا، لأن الأعمال الروتينية البسيطة تُؤتمت بشكل متزايد."],["Andererseits entstehen durch die Digitalisierung auch neue Berufe, etwa in der IT oder im Online-Marketing.","ومن ناحية أخرى، تنشأ بفضل الرقمنة مهن جديدة، مثلًا في تقنية المعلومات أو التسويق الإلكتروني."],["Entscheidend ist, dass Arbeitnehmer bereit sind, sich ständig weiterzubilden.","الأمر الحاسم أن يكون الموظفون مستعدين لتطوير أنفسهم باستمرار."],["Wer neue Kompetenzen erwirbt, hat auf dem Arbeitsmarkt deutlich bessere Chancen.","من يكتسب مهارات جديدة تكون فرصه في سوق العمل أفضل بكثير."],["Auch die Unternehmen tragen hier eine große Verantwortung.","والشركات أيضًا تتحمل مسؤولية كبيرة هنا."],["Sie sollten ihren Mitarbeitern Schulungen anbieten und sie bei der Umstellung unterstützen.","ينبغي أن تقدّم لموظفيها دورات تدريبية وأن تدعمهم في هذا التحول."],["Darüber hinaus müssen Fragen des Datenschutzes ernst genommen werden.","وعلاوة على ذلك يجب أن تؤخذ مسائل حماية البيانات بجدية."],["Meiner Meinung nach überwiegen die Chancen der Digitalisierung, wenn man sie verantwortungsvoll gestaltet.","في رأيي فرص الرقمنة تفوق مخاطرها إذا تعاملنا معها بمسؤولية."],["Wer sich dem Wandel verweigert, wird allerdings auf Dauer zurückbleiben.","لكن من يرفض التغيير سيتخلف على المدى الطويل."]]},{"t":"تغيّر المناخ: ماذا نستطيع أن نفعل؟","de":"Klimawandel – was können wir tun?","s":[["Der Klimawandel gehört zu den größten Herausforderungen unserer Zeit.","تغيّر المناخ من أكبر تحديات عصرنا."],["Die Temperaturen steigen weltweit, und extreme Wetterereignisse nehmen zu.","ترتفع درجات الحرارة في العالم كله، وتزداد الظواهر الجوية المتطرفة."],["Hauptursache ist der Ausstoß von Treibhausgasen, vor allem durch Verkehr, Industrie und Energieerzeugung.","السبب الرئيسي هو انبعاث غازات الاحتباس الحراري، ولا سيما من المواصلات والصناعة وإنتاج الطاقة."],["Die Folgen sind schon heute sichtbar: Gletscher schmelzen, und in manchen Regionen herrscht Wassermangel.","والعواقب ظاهرة منذ الآن: الأنهار الجليدية تذوب، وفي بعض المناطق يسود نقص في المياه."],["Um den Klimawandel zu bremsen, müssen vor allem die Regierungen handeln.","لإبطاء تغيّر المناخ يجب على الحكومات قبل غيرها أن تتحرك."],["Sie sollten erneuerbare Energien fördern und klimaschädliche Produkte teurer machen.","ينبغي أن تدعم الطاقات المتجددة وأن ترفع أسعار المنتجات الضارة بالمناخ."],["Doch auch jeder Einzelne kann einen Beitrag leisten.","لكن كل فرد أيضًا يستطيع أن يسهم."],["Wer zum Beispiel öfter das Fahrrad oder die Bahn nimmt, verringert seinen CO2-Ausstoß erheblich.","فمن يستخدم الدراجة أو القطار أكثر مثلًا يقلل انبعاثاته بدرجة كبيرة."],["Auch ein bewusster Konsum ist wichtig: weniger Fleisch, weniger Plastik, weniger Flüge.","والاستهلاك الواعي مهم أيضًا: لحم أقل، وبلاستيك أقل، ورحلات جوية أقل."],["Kritiker wenden ein, dass solche Maßnahmen allein nicht ausreichen.","يعترض المنتقدون بأن هذه الإجراءات وحدها لا تكفي."],["Das stimmt zwar, dennoch erhöhen sie den Druck auf Politik und Wirtschaft.","هذا صحيح، ومع ذلك فهي تزيد الضغط على السياسة والاقتصاد."],["Ich bin überzeugt, dass wir das Problem nur gemeinsam lösen können.","أنا مقتنع بأننا لن نحل هذه المشكلة إلا معًا."],["Es geht schließlich um die Zukunft unserer Kinder.","فالأمر في النهاية يتعلق بمستقبل أطفالنا."]]},{"t":"العمل من المنزل: المزايا والعيوب","de":"Homeoffice – Vor- und Nachteile","s":[["Seit einigen Jahren arbeiten immer mehr Menschen von zu Hause aus.","منذ بضع سنوات يعمل عدد متزايد من الناس من منازلهم."],["Dieses Modell bringt zahlreiche Vorteile mit sich.","يحمل هذا النموذج مزايا عديدة."],["Zunächst entfällt der Arbeitsweg, wodurch man Zeit und Geld spart.","أولًا لا يوجد طريق إلى العمل، فيوفّر المرء الوقت والمال."],["Außerdem lassen sich Familie und Beruf leichter miteinander vereinbaren.","كما يصبح التوفيق بين الأسرة والعمل أسهل."],["Viele Beschäftigte berichten, dass sie zu Hause konzentrierter arbeiten können.","ويذكر كثير من الموظفين أنهم يستطيعون التركيز أكثر في المنزل."],["Dem stehen jedoch auch Nachteile gegenüber.","لكن في المقابل توجد عيوب أيضًا."],["So fehlt der persönliche Kontakt zu den Kollegen, was zu Einsamkeit führen kann.","فالتواصل المباشر مع الزملاء يغيب، مما قد يؤدي إلى الشعور بالوحدة."],["Zudem verschwimmen die Grenzen zwischen Arbeit und Freizeit.","كما تتداخل الحدود بين العمل ووقت الفراغ."],["Wer abends noch schnell E-Mails beantwortet, kann schlecht abschalten.","ومن يرد على الرسائل الإلكترونية في المساء لا يستطيع الانفصال عن العمل جيدًا."],["Nicht zuletzt ist nicht jeder Beruf für das Homeoffice geeignet.","وأخيرًا، ليست كل مهنة مناسبة للعمل من المنزل."],["Eine Pflegekraft oder ein Handwerker muss natürlich vor Ort sein.","فالممرض أو الحرفي يجب بالطبع أن يكون حاضرًا في المكان."],["Meiner Ansicht nach ist ein Mix aus Büro und Homeoffice die beste Lösung.","في رأيي الحل الأمثل هو المزج بين المكتب والعمل من المنزل."],["So können die Vorteile beider Modelle genutzt werden.","وبذلك يمكن الاستفادة من مزايا النموذجين."]]},{"t":"التعلّم مدى الحياة","de":"Lebenslanges Lernen","s":[["Früher hat man einen Beruf gelernt und ihn dann sein ganzes Leben lang ausgeübt.","في الماضي كان المرء يتعلم مهنة ثم يمارسها طوال حياته."],["Heute ist das kaum noch vorstellbar.","أما اليوم فهذا يكاد يكون غير متصوَّر."],["Durch den technischen Fortschritt verändern sich die Anforderungen im Beruf ständig.","بسبب التقدم التقني تتغير متطلبات العمل باستمرار."],["Wissen, das heute aktuell ist, kann in wenigen Jahren schon veraltet sein.","المعرفة الحديثة اليوم قد تصبح قديمة بعد سنوات قليلة."],["Deshalb spricht man vom lebenslangen Lernen.","لذلك يُتحدث عن التعلّم مدى الحياة."],["Gemeint ist damit, dass man sich auch nach der Schule und dem Studium weiterbildet.","والمقصود أن يواصل المرء تطوير نفسه حتى بعد المدرسة والجامعة."],["Das kann ein Sprachkurs sein, ein Online-Seminar oder eine Fortbildung im Betrieb.","قد يكون ذلك دورة لغة، أو ندوة عبر الإنترنت، أو تدريبًا في مكان العمل."],["Lebenslanges Lernen hat nicht nur berufliche Vorteile.","وللتعلم مدى الحياة فوائد لا تقتصر على العمل."],["Es hält auch geistig fit und stärkt das Selbstbewusstsein.","فهو يحافظ أيضًا على نشاط العقل ويعزز الثقة بالنفس."],["Allerdings fehlt vielen Menschen neben Arbeit und Familie die Zeit dafür.","لكن كثيرًا من الناس لا يجدون وقتًا لذلك إلى جانب العمل والأسرة."],["Zudem sind manche Kurse sehr teuer.","كما أن بعض الدورات مكلفة جدًا."],["Hier sollten Staat und Arbeitgeber mehr Unterstützung anbieten.","وهنا ينبغي أن تقدّم الدولة وأصحاب العمل دعمًا أكبر."],["Ich selbst lerne gerade Deutsch und merke, wie sehr mich das bereichert.","أنا نفسي أتعلم الألمانية الآن، وألاحظ كم يثريني ذلك."]]}],"B2.2":[{"t":"وسائل التواصل الاجتماعي والديمقراطية","de":"Soziale Medien und Demokratie","s":[["Soziale Medien haben die Art und Weise, wie wir uns informieren, stark verändert.","غيّرت وسائل التواصل الاجتماعي طريقة حصولنا على المعلومات تغييرًا كبيرًا."],["Kritiker behaupten, sie schadeten der Demokratie mehr, als sie ihr nützten.","يزعم المنتقدون أنها تضر بالديمقراطية أكثر مما تنفعها."],["Als Grund wird häufig genannt, dass sich Falschmeldungen dort rasend schnell verbreiteten.","وكثيرًا ما يُذكر سببًا لذلك أن الأخبار الكاذبة تنتشر هناك بسرعة هائلة."],["Hinzu kommt, dass Algorithmen vor allem Inhalte anzeigen, die unsere eigene Meinung bestätigen.","يضاف إلى ذلك أن الخوارزميات تعرض غالبًا المحتوى الذي يؤكد آراءنا."],["Infolgedessen entstehen sogenannte Filterblasen, in denen andere Sichtweisen kaum noch vorkommen.","ونتيجة لذلك تنشأ ما تُسمّى فقاعات التصفية، التي تكاد لا تظهر فيها وجهات النظر الأخرى."],["Dies kann die gesellschaftliche Spaltung verstärken.","وقد يزيد هذا من الانقسام في المجتمع."],["Andererseits darf man nicht übersehen, dass soziale Medien auch große Chancen bieten.","لكن من ناحية أخرى لا ينبغي أن نغفل أن وسائل التواصل تتيح فرصًا كبيرة أيضًا."],["Bürger können sich kostenlos informieren, ihre Meinung äußern und sich politisch engagieren.","فيستطيع المواطنون الحصول على المعلومات مجانًا، والتعبير عن آرائهم، والمشاركة في السياسة."],["Zahlreiche Protestbewegungen wären ohne sie kaum möglich gewesen.","وكانت حركات احتجاجية عديدة شبه مستحيلة من دونها."],["Das eigentliche Problem liegt also nicht in den Plattformen selbst, sondern im Umgang mit ihnen.","فالمشكلة الحقيقية إذن لا تكمن في المنصات ذاتها، بل في طريقة التعامل معها."],["Meiner Auffassung nach müsste die Medienkompetenz bereits in der Schule gefördert werden.","في رأيي ينبغي تعزيز الوعي الإعلامي منذ المدرسة."],["Gleichzeitig sollten die Betreiber gesetzlich verpflichtet werden, gegen Hass und Falschinformationen vorzugehen.","وفي الوقت نفسه ينبغي إلزام مشغّلي المنصات قانونيًا بمكافحة الكراهية والمعلومات المضللة."],["Nur so können soziale Medien die Demokratie stärken, statt sie zu gefährden.","بهذا فقط تستطيع وسائل التواصل أن تقوّي الديمقراطية بدلًا من أن تهددها."]]},{"t":"الهجرة والاندماج","de":"Migration und Integration","s":[["Deutschland ist seit Jahrzehnten ein Einwanderungsland.","ألمانيا بلد هجرة منذ عقود."],["Millionen Menschen sind hierher gekommen, um zu arbeiten, zu studieren oder Schutz zu suchen.","جاء ملايين الناس إلى هنا للعمل أو الدراسة أو طلب الحماية."],["Da die Bevölkerung altert und Fachkräfte fehlen, ist die Wirtschaft auf Zuwanderung angewiesen.","وبما أن السكان يتقدمون في السن ويوجد نقص في العمالة الماهرة، فإن الاقتصاد يعتمد على الهجرة."],["Damit Integration gelingt, müssen jedoch beide Seiten ihren Beitrag leisten.","لكن لكي ينجح الاندماج، يجب أن يسهم الطرفان."],["Von den Zugewanderten wird erwartet, dass sie die Sprache lernen und die Grundwerte der Gesellschaft respektieren.","يُنتظر من المهاجرين أن يتعلموا اللغة وأن يحترموا القيم الأساسية للمجتمع."],["Die Aufnahmegesellschaft wiederum sollte ihnen offen begegnen und faire Chancen bieten.","وفي المقابل ينبغي أن يتعامل معهم المجتمع المستقبِل بانفتاح وأن يمنحهم فرصًا عادلة."],["In der Praxis gibt es allerdings noch viele Hürden.","لكن في الواقع ما زالت هناك عقبات كثيرة."],["So werden ausländische Abschlüsse oft nicht anerkannt, sodass gut ausgebildete Menschen unter ihrer Qualifikation arbeiten.","فالشهادات الأجنبية مثلًا كثيرًا ما لا يُعترف بها، فيعمل أشخاص مؤهلون جيدًا في وظائف أدنى من مؤهلاتهم."],["Auch Vorurteile und Diskriminierung erschweren die Teilhabe.","كما تعيق الأحكام المسبقة والتمييز المشاركة."],["Studien zeigen, dass Bewerber mit ausländischem Namen seltener zu Vorstellungsgesprächen eingeladen werden.","وتُظهر الدراسات أن المتقدمين ذوي الأسماء الأجنبية يُدعَون إلى مقابلات العمل بنسبة أقل."],["Dabei bereichert kulturelle Vielfalt die Gesellschaft in vielerlei Hinsicht.","مع أن التنوع الثقافي يثري المجتمع من جوانب كثيرة."],["Meiner Meinung nach ist Integration kein Ziel, das man einmal erreicht, sondern ein ständiger Prozess.","في رأيي الاندماج ليس هدفًا يُبلغ مرة واحدة، بل عملية مستمرة."],["Sie gelingt nur, wenn alle bereit sind, voneinander zu lernen.","ولا ينجح إلا إذا كان الجميع مستعدين للتعلم من بعضهم."]]},{"t":"الاستهلاك والاستدامة","de":"Konsum und Nachhaltigkeit","s":[["Wir leben in einer Konsumgesellschaft.","نحن نعيش في مجتمع استهلاكي."],["Kleidung, Elektronik und Lebensmittel sind so günstig und leicht verfügbar wie nie zuvor.","أصبحت الملابس والأجهزة الإلكترونية والمواد الغذائية أرخص وأيسر منالًا من أي وقت مضى."],["Viele Produkte werden gekauft, kurz benutzt und dann weggeworfen.","كثير من المنتجات تُشترى، وتُستعمل قليلًا، ثم تُرمى."],["Diese Wegwerfmentalität hat erhebliche Folgen für die Umwelt.","ولعقلية الرمي هذه عواقب جسيمة على البيئة."],["Für die Herstellung eines einzigen T-Shirts werden zum Beispiel tausende Liter Wasser benötigt.","فلإنتاج قميص واحد مثلًا تُستهلك آلاف اللترات من الماء."],["Hinzu kommen oft schlechte Arbeitsbedingungen in den Produktionsländern.","يضاف إلى ذلك غالبًا ظروف عمل سيئة في بلدان الإنتاج."],["Immer mehr Verbraucher wollen deshalb nachhaltiger einkaufen.","لذلك يريد عدد متزايد من المستهلكين أن يتسوقوا بطريقة أكثر استدامة."],["Sie achten auf Siegel, kaufen gebrauchte Waren oder reparieren Dinge, statt sie zu ersetzen.","فهم ينتبهون إلى علامات الجودة، ويشترون سلعًا مستعملة، أو يصلحون الأشياء بدلًا من استبدالها."],["Allerdings sind nachhaltige Produkte häufig teurer, was nicht jeder sich leisten kann.","لكن المنتجات المستدامة غالبًا أغلى، وليس بمقدور الجميع شراؤها."],["Kritiker bemängeln außerdem, dass manche Firmen nur so tun, als wären sie umweltfreundlich.","وينتقد المنتقدون أيضًا أن بعض الشركات تتظاهر بأنها صديقة للبيئة."],["Man spricht in diesem Zusammenhang von Greenwashing.","ويُسمّى ذلك في هذا السياق الغسل الأخضر."],["Ich bin der Ansicht, dass nicht nur die Verbraucher, sondern auch der Gesetzgeber in der Pflicht ist.","أرى أن المسؤولية لا تقع على المستهلكين وحدهم، بل على المشرّع أيضًا."],["Klare Regeln würden nachhaltigen Konsum für alle erleichtern.","فالقواعد الواضحة ستيسّر الاستهلاك المستدام على الجميع."]]},{"t":"المساواة بين الرجل والمرأة","de":"Gleichberechtigung","s":[["Laut Grundgesetz sind Männer und Frauen in Deutschland gleichberechtigt.","وفق الدستور، يتمتع الرجال والنساء في ألمانيا بحقوق متساوية."],["Im Alltag sieht die Realität jedoch häufig anders aus.","لكن الواقع في الحياة اليومية كثيرًا ما يكون مختلفًا."],["Frauen verdienen im Durchschnitt immer noch weniger als Männer.","فما زالت النساء يكسبن في المتوسط أقل من الرجال."],["Dieser Unterschied wird unter anderem darauf zurückgeführt, dass Frauen häufiger in Teilzeit arbeiten.","ويُعزى هذا الفرق من بين أسباب أخرى إلى أن النساء يعملن بدوام جزئي أكثر."],["Sie übernehmen nach wie vor den größten Teil der Kinderbetreuung und der Hausarbeit.","فهن ما زلن يتحملن الجزء الأكبر من رعاية الأطفال والأعمال المنزلية."],["Auch in Führungspositionen sind Frauen deutlich unterrepräsentiert.","كما أن تمثيل النساء في المناصب القيادية أقل بكثير."],["Um das zu ändern, wurden verschiedene Maßnahmen eingeführt, zum Beispiel das Elterngeld.","ولتغيير ذلك، أُقرّت إجراءات مختلفة، مثل علاوة الوالدين."],["Es soll Vätern ermöglichen, eine Zeit lang zu Hause bei ihren Kindern zu bleiben.","والهدف منها أن يتمكن الآباء من البقاء في البيت مع أطفالهم مدة من الزمن."],["Ob eine gesetzliche Frauenquote sinnvoll ist, wird dagegen kontrovers diskutiert.","أما هل الحصة الإلزامية للنساء في المناصب فكرة مفيدة، فهذا محل جدل واسع."],["Befürworter argumentieren, ohne Quote würde sich zu wenig ändern.","يحتج المؤيدون بأنه من دون الحصة الإلزامية لن يتغير إلا القليل."],["Gegner halten dagegen, dass allein die Qualifikation zählen sollte.","ويرد المعارضون بأن المؤهلات وحدها هي التي ينبغي أن تُحتسب."],["Meiner Meinung nach beginnt echte Gleichberechtigung bereits in der Erziehung.","في رأيي تبدأ المساواة الحقيقية من التربية."],["Wenn Jungen und Mädchen die gleichen Chancen bekommen, profitiert die ganze Gesellschaft davon.","عندما يحصل الأولاد والبنات على الفرص نفسها، يستفيد المجتمع كله."]]}],"C1.1":[{"t":"الذكاء الاصطناعي وعالم العمل","de":"Künstliche Intelligenz und Arbeitswelt","s":[["Kaum eine Technologie hat in den vergangenen Jahren so viel Aufmerksamkeit erregt wie die künstliche Intelligenz.","لم تحظَ أي تقنية في السنوات الماضية باهتمام يضاهي الاهتمام بالذكاء الاصطناعي."],["Programme, die Texte verfassen, Bilder erzeugen oder medizinische Befunde auswerten, sind längst keine Zukunftsmusik mehr.","فالبرامج التي تكتب النصوص وتنشئ الصور وتحلل النتائج الطبية لم تعد ضربًا من الخيال."],["Befürworter sehen darin die Chance, Routineaufgaben abzugeben und sich auf kreative Tätigkeiten zu konzentrieren.","ويرى المؤيدون في ذلك فرصة للتخلص من المهام الروتينية والتفرغ للأعمال الإبداعية."],["Kritiker hingegen warnen vor einem massiven Verlust von Arbeitsplätzen, insbesondere im Dienstleistungssektor.","أما المنتقدون فيحذّرون من فقدان واسع للوظائف، لا سيما في قطاع الخدمات."],["Bemerkenswert ist, dass diesmal nicht nur einfache, sondern auch hochqualifizierte Tätigkeiten betroffen sein könnten.","واللافت أن الأمر هذه المرة قد لا يقتصر على الأعمال البسيطة، بل قد يطال أيضًا الأعمال التي تتطلب تأهيلًا عاليًا."],["Übersetzer, Juristen und sogar Programmierer stellen sich zunehmend die Frage, wie sich ihr Berufsbild verändern wird.","فالمترجمون والقانونيون بل والمبرمجون يتساءلون بشكل متزايد عن الكيفية التي ستتغير بها مهنهم."],["Historische Erfahrungen legen allerdings nahe, dass technologischer Wandel stets auch neue Berufe hervorgebracht hat.","غير أن التجارب التاريخية توحي بأن التحول التقني أفرز دائمًا مهنًا جديدة أيضًا."],["Entscheidend wird sein, ob es gelingt, die Beschäftigten rechtzeitig weiterzubilden.","وسيكون الحاسم هو ما إذا كان سيُتاح تأهيل العاملين في الوقت المناسب."],["Darüber hinaus stellen sich ethische Fragen, etwa nach der Verantwortung für fehlerhafte Entscheidungen einer Maschine.","وفضلًا عن ذلك تُطرح أسئلة أخلاقية، كالسؤال عن المسؤولية عن القرارات الخاطئة التي تتخذها الآلة."],["Auch der Datenschutz gerät in den Fokus, da KI-Systeme auf riesige Datenmengen angewiesen sind.","كما تتصدر حماية البيانات الاهتمام، لأن أنظمة الذكاء الاصطناعي تعتمد على كميات هائلة من البيانات."],["Ich bin der Auffassung, dass wir die Technologie weder verteufeln noch unkritisch feiern sollten.","وأرى أننا لا ينبغي أن نشيطن هذه التقنية ولا أن نحتفي بها دون نقد."],["Vielmehr bedarf es klarer Regeln, die Innovation ermöglichen und zugleich den Menschen in den Mittelpunkt stellen.","بل نحتاج إلى قواعد واضحة تتيح الابتكار وتضع الإنسان في الوقت نفسه في المركز."]]},{"t":"تكافؤ الفرص في التعليم","de":"Bildungsgerechtigkeit","s":[["In kaum einem anderen Industrieland hängt der Bildungserfolg so stark von der sozialen Herkunft ab wie in Deutschland.","يكاد لا يوجد بلد صناعي آخر يرتبط فيه النجاح الدراسي بالخلفية الاجتماعية بقدر ارتباطه بها في ألمانيا."],["Kinder aus Akademikerfamilien besuchen deutlich häufiger ein Gymnasium als Kinder, deren Eltern keinen Abschluss haben.","فأطفال الأسر الأكاديمية يلتحقون بالمدرسة الثانوية العليا أكثر بكثير من الأطفال الذين لا يحمل آباؤهم شهادات."],["Ein Grund dafür ist die frühe Aufteilung auf verschiedene Schulformen nach der vierten Klasse.","ومن أسباب ذلك التوزيع المبكر على أنواع مختلفة من المدارس بعد الصف الرابع."],["Zu diesem Zeitpunkt können Eltern mit höherem Bildungsniveau ihre Kinder oft besser unterstützen.","ففي هذه المرحلة يستطيع الآباء ذوو المستوى التعليمي الأعلى غالبًا دعم أطفالهم بشكل أفضل."],["Hinzu kommt, dass private Nachhilfe teuer ist und sich nicht alle Familien sie leisten können.","يضاف إلى ذلك أن الدروس الخصوصية مكلفة، ولا تقدر عليها كل الأسر."],["Auch sprachliche Hürden spielen eine Rolle, insbesondere bei Kindern mit Migrationshintergrund.","كما تؤدي العقبات اللغوية دورًا، ولا سيما لدى الأطفال ذوي الأصول المهاجرة."],["Experten fordern daher, frühkindliche Bildung auszubauen und Ganztagsschulen flächendeckend einzuführen.","لذلك يطالب الخبراء بتوسيع التعليم في الطفولة المبكرة وتعميم المدارس ذات اليوم الكامل."],["Zudem sollten Lehrkräfte besser darauf vorbereitet werden, mit heterogenen Klassen umzugehen.","كما ينبغي إعداد المعلمين بشكل أفضل للتعامل مع الصفوف غير المتجانسة."],["Kritiker entgegnen, dass mehr Geld allein das Problem nicht löse.","ويرد المنتقدون بأن زيادة الأموال وحدها لن تحل المشكلة."],["Entscheidend sei vielmehr eine Haltung, die jedes Kind unabhängig von seiner Herkunft fördert.","بل الحاسم في رأيهم هو موقف يدعم كل طفل بصرف النظر عن خلفيته."],["Meiner Ansicht nach ist Bildungsgerechtigkeit nicht nur eine Frage der Fairness, sondern auch der wirtschaftlichen Vernunft.","وفي رأيي أن تكافؤ الفرص في التعليم ليس مسألة عدالة فحسب، بل مسألة حكمة اقتصادية أيضًا."],["Eine Gesellschaft, die Talente ungenutzt lässt, verschenkt ihr eigenes Potenzial.","فالمجتمع الذي يهدر المواهب يفرّط في إمكاناته الذاتية."]]},{"t":"التحضّر ومستقبل المدن","de":"Urbanisierung und die Stadt der Zukunft","s":[["Bereits heute lebt mehr als die Hälfte der Weltbevölkerung in Städten, und der Anteil wächst weiter.","يعيش اليوم بالفعل أكثر من نصف سكان العالم في المدن، ولا تزال النسبة في ازدياد."],["Städte bieten Arbeitsplätze, Bildungsangebote und eine vielfältige Kultur.","فالمدن توفر فرص العمل والتعليم وثقافة متنوعة."],["Gleichzeitig stehen sie vor enormen Herausforderungen wie Wohnungsknappheit, Verkehrsstaus und Luftverschmutzung.","وفي الوقت نفسه تواجه تحديات هائلة مثل نقص المساكن والازدحام المروري وتلوث الهواء."],["Die steigenden Mieten verdrängen zunehmend Menschen mit geringem Einkommen an den Stadtrand.","فارتفاع الإيجارات يدفع ذوي الدخل المحدود بشكل متزايد إلى أطراف المدن."],["Stadtplaner setzen deshalb auf das Konzept der sogenannten Fünfzehn-Minuten-Stadt.","لذلك يعتمد مخططو المدن على مفهوم ما يُسمّى مدينة الخمس عشرة دقيقة."],["Gemeint ist, dass alle wichtigen Einrichtungen innerhalb einer Viertelstunde zu Fuß oder mit dem Rad erreichbar sein sollen.","والمقصود أن تكون جميع المرافق المهمة في متناول السكان خلال ربع ساعة سيرًا أو بالدراجة."],["Dadurch ließe sich der Autoverkehr reduzieren und die Lebensqualität erhöhen.","وبذلك يمكن تقليل حركة السيارات ورفع جودة الحياة."],["Auch begrünte Dächer und Fassaden gewinnen an Bedeutung, da sie die Hitze in den Sommermonaten mildern.","كما تكتسب الأسطح والواجهات المزروعة أهمية متزايدة، لأنها تخفف الحر في أشهر الصيف."],["Skeptiker geben jedoch zu bedenken, dass solche Projekte teuer sind und vor allem wohlhabende Viertel profitieren.","غير أن المتشككين ينبّهون إلى أن هذه المشاريع مكلفة، وأن الأحياء الميسورة هي المستفيد الأكبر منها."],["Eine zukunftsfähige Stadt muss daher nicht nur ökologisch, sondern auch sozial gerecht sein.","لذلك يجب أن تكون المدينة القادرة على مواجهة المستقبل عادلة اجتماعيًا لا بيئيًا فقط."],["Bezahlbarer Wohnraum ist dabei mindestens ebenso wichtig wie neue Radwege.","والسكن الميسور في ذلك لا يقل أهمية عن مسارات الدراجات الجديدة."],["Letztlich entscheidet die Beteiligung der Bürger darüber, ob die Stadt der Zukunft für alle lebenswert wird.","وفي النهاية تحدد مشاركة المواطنين ما إذا كانت مدينة المستقبل صالحة للعيش للجميع."]]},{"t":"النظام الصحي في مرحلة تحوّل","de":"Das Gesundheitssystem im Wandel","s":[["Das deutsche Gesundheitssystem gilt international als leistungsfähig, steht jedoch unter wachsendem Druck.","يُعد النظام الصحي الألماني على المستوى الدولي نظامًا كفئًا، لكنه يتعرض لضغط متزايد."],["Ein wesentlicher Faktor ist der demografische Wandel, denn die Bevölkerung wird immer älter.","ومن العوامل الأساسية التحول الديموغرافي، إذ يتقدم السكان في السن باستمرار."],["Ältere Menschen benötigen in der Regel mehr medizinische Versorgung und Pflege.","فكبار السن يحتاجون عادةً إلى قدر أكبر من الرعاية الطبية والتمريضية."],["Gleichzeitig herrscht vielerorts ein gravierender Mangel an Pflegekräften und Hausärzten.","وفي الوقت نفسه يسود في أماكن كثيرة نقص حاد في الممرضين وأطباء الأسرة."],["Insbesondere in ländlichen Regionen müssen Patienten oft lange Wege und Wartezeiten in Kauf nehmen.","ولا سيما في المناطق الريفية، حيث يضطر المرضى غالبًا إلى قطع مسافات طويلة وتحمّل فترات انتظار طويلة."],["Die Digitalisierung könnte hier Abhilfe schaffen, etwa durch Videosprechstunden oder die elektronische Patientenakte.","وقد تقدم الرقمنة حلًا هنا، مثلًا من خلال الاستشارات المرئية أو الملف الإلكتروني للمريض."],["Allerdings äußern viele Bürger Bedenken hinsichtlich der Sicherheit ihrer sensiblen Gesundheitsdaten.","غير أن كثيرًا من المواطنين يبدون تحفظات بشأن أمان بياناتهم الصحية الحساسة."],["Ein weiteres Problem sind die steigenden Kosten, die sich in höheren Krankenkassenbeiträgen niederschlagen.","ومن المشكلات الأخرى ارتفاع التكاليف، الذي ينعكس في زيادة اشتراكات التأمين الصحي."],["Manche Experten plädieren daher für mehr Prävention, um Krankheiten gar nicht erst entstehen zu lassen.","لذلك يدعو بعض الخبراء إلى مزيد من الوقاية حتى لا تنشأ الأمراض أصلًا."],["Andere fordern, die Arbeitsbedingungen in der Pflege deutlich zu verbessern, um den Beruf attraktiver zu machen.","ويطالب آخرون بتحسين ظروف العمل في التمريض تحسينًا كبيرًا لجعل المهنة أكثر جاذبية."],["Vermutlich wird nur eine Kombination verschiedener Maßnahmen langfristig zum Erfolg führen.","ومن المرجح أن مزيجًا من الإجراءات المختلفة وحده هو ما سيؤدي إلى النجاح على المدى الطويل."],["Klar ist jedenfalls, dass eine gute Gesundheitsversorgung nicht vom Wohnort abhängen darf.","والواضح على أي حال أن الرعاية الصحية الجيدة لا يجوز أن تتوقف على مكان السكن."]]}],"C1.2":[{"t":"العمل التطوعي والمجتمع المدني","de":"Ehrenamt und Zivilgesellschaft","s":[["Rund ein Drittel der Menschen in Deutschland engagiert sich ehrenamtlich.","يشارك نحو ثلث الناس في ألمانيا في العمل التطوعي."],["Sie trainieren Kinder im Sportverein, begleiten Geflüchtete zu Behörden oder unterstützen die Tafeln.","فهم يدرّبون الأطفال في الأندية الرياضية، ويرافقون اللاجئين إلى الدوائر الحكومية، أو يدعمون بنوك الطعام."],["Ohne dieses Engagement würden viele soziale Angebote schlichtweg nicht existieren.","ولولا هذا الالتزام لما وُجدت كثير من الخدمات الاجتماعية أصلًا."],["Die Motive der Ehrenamtlichen sind vielfältig: Manche möchten etwas zurückgeben, andere suchen Gemeinschaft.","ودوافع المتطوعين متنوعة: فبعضهم يريد رد الجميل، وآخرون يبحثون عن الانتماء إلى جماعة."],["Nicht wenige berichten, dass sie durch ihre Tätigkeit selbst an Selbstvertrauen gewonnen haben.","ويذكر كثيرون أنهم اكتسبوا من خلال نشاطهم مزيدًا من الثقة بالنفس."],["Dennoch klagen viele Vereine über Nachwuchsprobleme.","ومع ذلك تشكو جمعيات كثيرة من قلة الأعضاء الجدد."],["Junge Menschen engagieren sich zwar nach wie vor, bevorzugen aber kurzfristige Projekte statt dauerhafter Verpflichtungen.","فالشباب لا يزالون يشاركون، لكنهم يفضّلون المشاريع القصيرة على الالتزامات الدائمة."],["Zudem lässt sich ein Ehrenamt neben Beruf und Familie oft nur schwer vereinbaren.","كما يصعب غالبًا التوفيق بين العمل التطوعي والعمل والأسرة."],["Kritiker warnen außerdem davor, dass der Staat sich aus Aufgaben zurückzieht und sich auf Freiwillige verlässt.","ويحذّر المنتقدون أيضًا من أن تنسحب الدولة من مهامها وتعتمد على المتطوعين."],["Ehrenamt dürfe kein Ersatz für bezahlte Fachkräfte werden, so ihre Forderung.","فالعمل التطوعي، بحسب مطالبتهم، لا يجوز أن يصبح بديلًا عن المختصين المأجورين."],["Um das Engagement zu stärken, könnten Arbeitgeber zum Beispiel Freistellungen ermöglichen.","ولتعزيز هذا الالتزام يمكن لأصحاب العمل مثلًا أن يتيحوا للموظفين إجازات لهذا الغرض."],["Eine lebendige Zivilgesellschaft ist schließlich das Fundament jeder funktionierenden Demokratie.","فالمجتمع المدني الحيوي هو في النهاية أساس كل ديمقراطية فاعلة."]]},{"t":"التحول الديموغرافي والعلاقة بين الأجيال","de":"Demografischer Wandel und das Miteinander der Generationen","s":[["Die Lebenserwartung in Deutschland ist in den letzten Jahrzehnten stetig gestiegen, während die Geburtenrate niedrig bleibt.","ارتفع متوسط العمر المتوقع في ألمانيا باستمرار في العقود الأخيرة، بينما بقي معدل المواليد منخفضًا."],["Infolgedessen müssen immer weniger Erwerbstätige die Renten von immer mehr Ruheständlern finanzieren.","ونتيجة لذلك يتعين على عدد متناقص من العاملين تمويل معاشات عدد متزايد من المتقاعدين."],["Dieses Ungleichgewicht stellt das umlagefinanzierte Rentensystem vor erhebliche Probleme.","وهذا الخلل يضع نظام التقاعد القائم على التمويل التضامني أمام مشكلات كبيرة."],["Als mögliche Lösungen werden eine längere Lebensarbeitszeit oder eine stärkere private Vorsorge diskutiert.","ومن الحلول المطروحة للنقاش إطالة سنوات العمل أو تعزيز الادخار الخاص للتقاعد."],["Viele Jüngere befürchten jedoch, später selbst kaum noch eine angemessene Rente zu erhalten.","غير أن كثيرًا من الشباب يخشون ألا يحصلوا هم أنفسهم لاحقًا على معاش لائق."],["Daraus entsteht mitunter der Eindruck eines Konflikts zwischen den Generationen.","ومن هنا ينشأ أحيانًا انطباع بوجود صراع بين الأجيال."],["Untersuchungen zeigen allerdings, dass die Solidarität zwischen Jung und Alt im Alltag ausgeprägt ist.","غير أن الدراسات تُظهر أن التضامن بين الشباب وكبار السن واضح في الحياة اليومية."],["Großeltern betreuen ihre Enkel, und erwachsene Kinder pflegen ihre Eltern.","فالأجداد يرعون أحفادهم، والأبناء البالغون يعتنون بآبائهم."],["Auch Mehrgenerationenhäuser, in denen Menschen unterschiedlichen Alters zusammenleben, erfreuen sich wachsender Beliebtheit.","كما تحظى بيوت الأجيال المتعددة، التي يعيش فيها أشخاص من أعمار مختلفة معًا، بشعبية متزايدة."],["Ältere bringen ihre Lebenserfahrung ein, während Jüngere ihnen etwa im Umgang mit digitaler Technik helfen.","فكبار السن يقدّمون خبرتهم في الحياة، بينما يساعدهم الشباب مثلًا في التعامل مع التقنيات الرقمية."],["Der demografische Wandel ist also nicht nur eine Belastung, sondern auch eine Chance für neue Formen des Zusammenlebens.","فالتحول الديموغرافي إذن ليس عبئًا فحسب، بل فرصة أيضًا لأشكال جديدة من العيش المشترك."],["Entscheidend ist, dass die Politik faire Lösungen findet, die keine Generation überfordern.","والحاسم هو أن تجد السياسة حلولًا عادلة لا تثقل كاهل أي جيل."]]},{"t":"حماية البيانات في العصر الرقمي","de":"Datenschutz im digitalen Zeitalter","s":[["Jeden Tag hinterlassen wir unzählige digitale Spuren, oft ohne uns dessen bewusst zu sein.","نترك كل يوم آثارًا رقمية لا تُحصى، وغالبًا دون أن ندرك ذلك."],["Suchanfragen, Standortdaten und Einkäufe werden gespeichert und ausgewertet.","فعمليات البحث وبيانات الموقع والمشتريات تُحفظ وتُحلَّل."],["Unternehmen nutzen diese Informationen, um personalisierte Werbung zu schalten.","وتستخدم الشركات هذه المعلومات لعرض إعلانات مخصصة."],["Viele Nutzer akzeptieren dies als Preis für kostenlose Dienste.","ويقبل كثير من المستخدمين ذلك ثمنًا للخدمات المجانية."],["Datenschützer warnen jedoch davor, dass aus scheinbar harmlosen Daten detaillierte Persönlichkeitsprofile entstehen können.","غير أن المدافعين عن حماية البيانات يحذّرون من أن بيانات تبدو بريئة قد تنشأ منها ملفات شخصية مفصلة."],["Solche Profile könnten etwa bei der Kreditvergabe oder bei Bewerbungen gegen uns verwendet werden.","وقد تُستخدم هذه الملفات ضدنا مثلًا عند منح القروض أو في طلبات التوظيف."],["Mit der Datenschutz-Grundverordnung hat die Europäische Union strenge Regeln eingeführt.","وقد أقرّ الاتحاد الأوروبي قواعد صارمة من خلال اللائحة العامة لحماية البيانات."],["Dennoch klicken die meisten Menschen Datenschutzhinweise einfach weg, ohne sie zu lesen.","ومع ذلك يتجاوز معظم الناس إشعارات الخصوصية بنقرة دون قراءتها."],["Das liegt nicht zuletzt daran, dass diese Texte oft lang und schwer verständlich sind.","ويرجع ذلك ليس أقلّه إلى أن هذه النصوص غالبًا طويلة وصعبة الفهم."],["Es stellt sich daher die Frage, ob die Verantwortung allein beim Einzelnen liegen kann.","لذلك يُطرح السؤال عما إذا كان يمكن أن تقع المسؤولية على الفرد وحده."],["Meines Erachtens müssen Anbieter verpflichtet werden, datensparsame Voreinstellungen zu wählen.","وفي تقديري يجب إلزام مقدمي الخدمات باختيار إعدادات افتراضية تقلل جمع البيانات."],["Gleichzeitig sollte Medienkompetenz fester Bestandteil des Unterrichts werden.","وفي الوقت نفسه ينبغي أن يصبح الوعي الإعلامي جزءًا ثابتًا من التعليم المدرسي."]]},{"t":"السياحة: نعمة أم نقمة؟","de":"Tourismus – Segen oder Fluch?","s":[["Der Tourismus zählt weltweit zu den wichtigsten Wirtschaftszweigen.","تُعد السياحة من أهم القطاعات الاقتصادية في العالم."],["Er schafft Arbeitsplätze und bringt Einnahmen in Regionen, die sonst kaum Perspektiven hätten.","فهي توفر فرص العمل وتجلب الإيرادات إلى مناطق ما كانت لتجد آفاقًا لولاها."],["Für Länder wie Ägypten ist er eine unverzichtbare Devisenquelle.","وهي لبلدان مثل مصر مصدر لا غنى عنه للعملة الصعبة."],["Gleichzeitig leiden beliebte Reiseziele zunehmend unter dem sogenannten Overtourism.","وفي الوقت نفسه تعاني الوجهات السياحية الشهيرة بشكل متزايد مما يُسمّى السياحة المفرطة."],["In Städten wie Venedig oder Barcelona werden Einheimische durch steigende Mieten verdrängt.","ففي مدن مثل البندقية وبرشلونة يُدفع السكان المحليون إلى المغادرة بسبب ارتفاع الإيجارات."],["Wohnungen werden zunehmend als Ferienunterkünfte vermietet, statt dauerhaft bewohnt zu werden.","إذ تُؤجَّر الشقق بشكل متزايد للسياح بدلًا من أن يسكنها الناس بصفة دائمة."],["Hinzu kommen ökologische Belastungen durch Flugreisen und Kreuzfahrtschiffe.","يضاف إلى ذلك الأعباء البيئية الناتجة عن السفر الجوي والسفن السياحية."],["Einige Städte reagieren mit Eintrittsgebühren oder Begrenzungen der Besucherzahlen.","وتستجيب بعض المدن بفرض رسوم دخول أو بتحديد أعداد الزوار."],["Andere setzen auf sanften Tourismus, der Natur und Kultur respektiert.","ويعتمد غيرها على السياحة المستدامة التي تحترم الطبيعة والثقافة."],["Auch die Reisenden selbst können einen Beitrag leisten, etwa indem sie außerhalb der Hauptsaison reisen.","ويستطيع المسافرون أنفسهم أيضًا الإسهام، مثلًا بالسفر خارج موسم الذروة."],["Letztlich hängt es von der Steuerung ab, ob der Tourismus eher Segen oder Fluch ist.","وفي النهاية يتوقف الأمر على حسن الإدارة في كون السياحة نعمة أم نقمة."],["Ein Gleichgewicht zwischen wirtschaftlichem Nutzen und Lebensqualität der Bewohner ist unerlässlich.","فالتوازن بين المنفعة الاقتصادية وجودة حياة السكان أمر لا غنى عنه."]]}],"C2.1":[{"t":"اللغة والهوية","de":"Sprache und Identität","s":[["Sprache ist weit mehr als ein bloßes Mittel zur Verständigung.","اللغة أكثر بكثير من مجرد وسيلة للتفاهم."],["In ihr spiegeln sich Denkweisen, Werte und die Geschichte einer Gemeinschaft wider.","ففيها تنعكس أنماط التفكير والقيم وتاريخ الجماعة."],["Wer in eine neue Sprache eintaucht, erschließt sich daher nicht nur Vokabeln, sondern eine andere Sicht auf die Welt.","ومن يغوص في لغة جديدة لا يكتسب مفردات فحسب، بل رؤية مختلفة للعالم."],["Viele Migrantinnen und Migranten beschreiben das Gefühl, in jeder Sprache ein etwas anderer Mensch zu sein.","ويصف كثير من المهاجرين شعورهم بأنهم يصبحون أشخاصًا مختلفين قليلًا في كل لغة."],["Im Deutschen wirken sie vielleicht sachlicher, im Arabischen hingegen emotionaler.","فقد يبدون بالألمانية أكثر موضوعية، وبالعربية أكثر عاطفية."],["Diese Mehrstimmigkeit kann bereichernd sein, aber auch Verunsicherung hervorrufen.","وقد يكون هذا التعدد في الأصوات مثريًا، لكنه قد يثير أيضًا شعورًا بعدم اليقين."],["Nicht selten fühlen sich Kinder aus Einwandererfamilien zwischen zwei Welten hin- und hergerissen.","وليس نادرًا أن يشعر أبناء الأسر المهاجرة بأنهم ممزقون بين عالمين."],["Die Herkunftssprache verbindet sie mit den Großeltern, die Landessprache mit Schule und Freundeskreis.","فلغة الأصل تربطهم بأجدادهم، ولغة البلد تربطهم بالمدرسة ودائرة الأصدقاء."],["Lange Zeit galt Mehrsprachigkeit in Deutschland eher als Integrationshindernis denn als Ressource.","وقد ظل تعدد اللغات في ألمانيا مدة طويلة يُعد عائقًا أمام الاندماج أكثر منه موردًا."],["Inzwischen setzt sich zunehmend die Erkenntnis durch, dass die Pflege der Erstsprache das Erlernen weiterer Sprachen sogar begünstigt.","أما اليوم فيترسخ بشكل متزايد الإدراك بأن رعاية اللغة الأم تيسّر بل تشجع تعلم لغات أخرى."],["Identität ist demnach nichts Statisches, sondern ein fortwährender Aushandlungsprozess.","فالهوية إذن ليست شيئًا ثابتًا، بل عملية تفاوض مستمرة."],["Wer mehrere Sprachen spricht, verfügt nicht über eine halbe, sondern über eine erweiterte Identität.","ومن يتكلم لغات عدة لا يملك نصف هوية، بل هوية موسَّعة."]]},{"t":"حرية الفن وحدودها","de":"Kunstfreiheit und ihre Grenzen","s":[["Die Freiheit der Kunst ist im Grundgesetz ausdrücklich geschützt.","حرية الفن محمية صراحة في الدستور الألماني."],["Sie umfasst nicht nur das Schaffen eines Werkes, sondern auch dessen Darbietung und Verbreitung.","وهي لا تشمل إبداع العمل فحسب، بل عرضه ونشره أيضًا."],["Gerade provokante Kunst erfüllt eine wichtige gesellschaftliche Funktion, indem sie Tabus infrage stellt.","فالفن الاستفزازي بالذات يؤدي وظيفة اجتماعية مهمة بمساءلته المحرّمات."],["Doch wo endet künstlerische Freiheit, und wo beginnt die Verletzung der Rechte anderer?","ولكن أين تنتهي الحرية الفنية، وأين يبدأ المساس بحقوق الآخرين؟"],["Diese Frage stellt sich etwa dann, wenn religiöse Gefühle verletzt oder reale Personen bloßgestellt werden.","ويُطرح هذا السؤال مثلًا عندما تُجرح المشاعر الدينية أو يُشهَّر بأشخاص حقيقيين."],["Gerichte müssen in solchen Fällen eine sorgfältige Abwägung zwischen gleichrangigen Grundrechten vornehmen.","وعلى المحاكم في مثل هذه الحالات أن توازن بعناية بين حقوق أساسية متساوية في المرتبة."],["In jüngster Zeit wird zudem kontrovers diskutiert, wer welche Geschichten erzählen darf.","وفي الآونة الأخيرة يدور كذلك جدل حول من يحق له أن يروي أي قصص."],["Während die einen vor kultureller Aneignung warnen, sehen andere darin eine Einschränkung der Fantasie.","فبينما يحذّر بعضهم من الاستيلاء الثقافي، يرى آخرون في ذلك تقييدًا للخيال."],["Hinzu kommt der Druck sozialer Medien, wo Empörung binnen Stunden zu Boykottaufrufen führen kann.","يضاف إلى ذلك ضغط وسائل التواصل الاجتماعي، حيث قد يتحول السخط في غضون ساعات إلى دعوات للمقاطعة."],["Manche Kunstschaffende üben deshalb bereits vorauseilende Selbstzensur.","لذلك يمارس بعض الفنانين رقابة ذاتية استباقية."],["Eine offene Gesellschaft muss es jedoch aushalten, mit Werken konfrontiert zu werden, die verstören.","غير أن المجتمع المنفتح يجب أن يحتمل مواجهة أعمال مزعجة."],["Kritik an Kunst ist legitim, ihre Unterdrückung hingegen gefährdet die Freiheit aller.","فنقد الفن مشروع، أما قمعه فيهدد حرية الجميع."]]},{"t":"الحقيقة في عصر ما بعد الحقائق","de":"Wahrheit im postfaktischen Zeitalter","s":[["Der Begriff postfaktisch beschreibt eine Situation, in der Gefühle die öffentliche Meinung stärker prägen als überprüfbare Tatsachen.","يصف مصطلح «ما بعد الحقائق» حالة تشكّل فيها المشاعر الرأي العام أكثر مما تشكّله الحقائق القابلة للتحقق."],["Falschmeldungen verbreiten sich im Netz nachweislich schneller als deren Richtigstellung.","وقد ثبت أن الأخبار الكاذبة تنتشر على الإنترنت أسرع من تصحيحها."],["Dies liegt unter anderem daran, dass sie häufig emotionaler und überraschender formuliert sind.","ويرجع ذلك من بين أمور أخرى إلى أنها غالبًا ما تُصاغ بطريقة أكثر إثارة للعواطف والمفاجأة."],["Zugleich hat das Vertrauen in traditionelle Institutionen wie Wissenschaft und Presse in Teilen der Bevölkerung abgenommen.","وفي الوقت نفسه تراجعت ثقة بعض فئات السكان في المؤسسات التقليدية كالعلم والصحافة."],["Wer der etablierten Berichterstattung misstraut, sucht nach alternativen Quellen, die das eigene Weltbild bestätigen.","فمن لا يثق بالتغطية الإعلامية الراسخة يبحث عن مصادر بديلة تؤكد رؤيته للعالم."],["Algorithmen verstärken diese Tendenz, indem sie bevorzugt Inhalte anzeigen, die Aufmerksamkeit erzeugen.","وتعزز الخوارزميات هذا الاتجاه بعرضها المحتوى الذي يجذب الانتباه بالدرجة الأولى."],["Mit dem Aufkommen täuschend echter KI-generierter Bilder und Videos dürfte sich das Problem noch verschärfen.","ومع ظهور الصور والفيديوهات المولّدة بالذكاء الاصطناعي التي تبدو حقيقية على نحو مخادع، يُرجَّح أن تتفاقم المشكلة."],["Faktenchecks sind zwar wichtig, erreichen jedoch oft nicht diejenigen, die einer Falschinformation bereits aufgesessen sind.","والتحقق من الحقائق مهم بلا شك، لكنه غالبًا لا يصل إلى من وقعوا فعلًا ضحية للمعلومات المضللة."],["Nachhaltiger erscheint es, die Fähigkeit zum kritischen Denken bereits früh zu fördern.","ويبدو أكثر استدامة أن تُنمّى القدرة على التفكير النقدي في سن مبكرة."],["Dazu gehört, Quellen zu prüfen, Absichten zu hinterfragen und die eigene Voreingenommenheit zu erkennen.","ويشمل ذلك فحص المصادر، ومساءلة النوايا، وإدراك التحيز الذاتي."],["Wahrheit ist keine Frage des Geschmacks, sondern Grundlage jeder vernünftigen Debatte.","فالحقيقة ليست مسألة ذوق، بل أساس كل نقاش عقلاني."],["Eine Demokratie, die sich nicht mehr auf gemeinsame Tatsachen verständigen kann, verliert ihre Handlungsfähigkeit.","والديمقراطية التي لم تعد قادرة على الاتفاق على حقائق مشتركة تفقد قدرتها على الفعل."]]},{"t":"العولمة والتنوع الثقافي","de":"Globalisierung und kulturelle Vielfalt","s":[["Die Globalisierung hat die Welt in beispielloser Weise zusammenrücken lassen.","قرّبت العولمة بين أطراف العالم على نحو غير مسبوق."],["Waren, Informationen und Menschen überwinden heute Grenzen mit einer Leichtigkeit, die früher undenkbar war.","فالسلع والمعلومات والبشر يعبرون الحدود اليوم بسهولة لم تكن متصورة في الماضي."],["Kritiker befürchten allerdings eine schleichende Vereinheitlichung der Kulturen.","غير أن المنتقدين يخشون توحيدًا زاحفًا للثقافات."],["In nahezu jeder Großstadt findet man dieselben Modeketten, Fast-Food-Restaurants und Filmproduktionen.","ففي كل مدينة كبرى تقريبًا تجد سلاسل الأزياء نفسها، ومطاعم الوجبات السريعة نفسها، والإنتاجات السينمائية نفسها."],["Lokale Traditionen und kleinere Sprachen geraten dadurch unter Druck.","وبذلك تتعرض التقاليد المحلية واللغات الأصغر للضغط."],["Andererseits ermöglicht die Vernetzung, dass auch Randkulturen ein weltweites Publikum erreichen.","ومن ناحية أخرى يتيح الترابط أن تصل حتى الثقافات الهامشية إلى جمهور عالمي."],["Musik aus Westafrika oder Serien aus Korea erfreuen sich heute internationaler Beliebtheit.","فالموسيقى من غرب أفريقيا أو المسلسلات الكورية تحظى اليوم بشعبية دولية."],["Kultur entsteht zudem seit jeher durch Austausch und Vermischung, nicht durch Abschottung.","كما أن الثقافة تنشأ منذ الأزل من التبادل والامتزاج، لا من الانغلاق."],["Die arabische Wissenschaft des Mittelalters etwa baute auf griechischem, persischem und indischem Wissen auf.","فالعلم العربي في العصور الوسطى مثلًا قام على المعرفة اليونانية والفارسية والهندية."],["Entscheidend ist folglich nicht, ob Kulturen einander beeinflussen, sondern unter welchen Bedingungen dies geschieht.","فالحاسم إذن ليس ما إذا كانت الثقافات تتأثر ببعضها، بل في أي ظروف يحدث ذلك."],["Wo wirtschaftliche Macht ungleich verteilt ist, droht der Austausch zur Einbahnstraße zu werden.","فحيث تتوزع القوة الاقتصادية بشكل غير متكافئ، يوشك التبادل أن يصبح طريقًا ذا اتجاه واحد."],["Kulturelle Vielfalt zu bewahren bedeutet daher, faire Bedingungen für den Dialog zu schaffen.","لذلك فإن صون التنوع الثقافي يعني تهيئة ظروف عادلة للحوار."]]}],"C2.2":[{"t":"التقدم العلمي والمسؤولية","de":"Wissenschaftlicher Fortschritt und Verantwortung","s":[["Die moderne Gentechnik eröffnet Möglichkeiten, die noch vor wenigen Jahrzehnten als Science-Fiction galten.","تفتح الهندسة الوراثية الحديثة آفاقًا كانت قبل عقود قليلة تُعد من الخيال العلمي."],["Mit Verfahren wie CRISPR lassen sich Gene gezielt verändern, um etwa Erbkrankheiten zu heilen.","فبتقنيات مثل كريسبر يمكن تعديل الجينات بدقة، مثلًا لعلاج الأمراض الوراثية."],["Kaum jemand würde bestreiten, dass die Heilung schwerer Krankheiten ein legitimes Ziel ist.","ولا يكاد أحد ينكر أن علاج الأمراض الخطيرة هدف مشروع."],["Problematisch wird es jedoch, sobald Eingriffe an der menschlichen Keimbahn vorgenommen werden.","غير أن الأمر يصبح إشكاليًا حالما تُجرى تدخلات في الخط الجرثومي للإنسان."],["Solche Veränderungen würden an alle nachfolgenden Generationen weitergegeben, ohne dass diese zustimmen könnten.","فمثل هذه التعديلات ستنتقل إلى جميع الأجيال اللاحقة دون أن يتمكن أفرادها من الموافقة عليها."],["Zudem ist die Grenze zwischen Therapie und Optimierung fließend.","كما أن الحد الفاصل بين العلاج والتحسين متداخل."],["Was heute der Vermeidung einer Krankheit dient, könnte morgen der Auswahl erwünschter Eigenschaften dienen.","فما يخدم اليوم تجنب مرض ما قد يخدم غدًا اختيار صفات مرغوبة."],["Kritiker befürchten eine Gesellschaft, in der genetische Merkmale über Lebenschancen entscheiden.","ويخشى المنتقدون مجتمعًا تحدد فيه السمات الوراثية فرص الحياة."],["Befürworter halten dem entgegen, dass jede neue Technologie anfangs Ängste ausgelöst habe.","ويرد المؤيدون بأن كل تقنية جديدة أثارت في بدايتها مخاوف."],["Die Wissenschaft allein kann diese Fragen jedoch nicht beantworten, da sie über ihr Fachgebiet hinausreichen.","غير أن العلم وحده لا يستطيع الإجابة عن هذه الأسئلة، لأنها تتجاوز نطاق تخصصه."],["Vielmehr bedarf es eines breiten gesellschaftlichen Diskurses, in dem ethische, rechtliche und soziale Aspekte abgewogen werden.","بل نحتاج إلى نقاش مجتمعي واسع تُوازَن فيه الجوانب الأخلاقية والقانونية والاجتماعية."],["Fortschritt ohne Verantwortung wäre letztlich ebenso gefährlich wie Verantwortung ohne Mut zum Fortschritt.","فالتقدم بلا مسؤولية سيكون في النهاية بالخطورة نفسها التي تنطوي عليها مسؤولية تفتقر إلى الجرأة على التقدم."]]},{"t":"السعادة والرخاء: هل نحتاج إلى النمو؟","de":"Glück und Wohlstand – brauchen wir Wachstum?","s":[["Seit Jahrzehnten gilt Wirtschaftswachstum als zentraler Maßstab für den Erfolg einer Gesellschaft.","يُعد النمو الاقتصادي منذ عقود المقياس المحوري لنجاح المجتمع."],["Das Bruttoinlandsprodukt sagt jedoch wenig darüber aus, wie zufrieden die Menschen tatsächlich sind.","غير أن الناتج المحلي الإجمالي لا يقول الكثير عن مدى رضا الناس فعلًا."],["Glücksforscher haben festgestellt, dass zusätzliches Einkommen ab einem gewissen Niveau kaum noch zu mehr Zufriedenheit führt.","وقد لاحظ باحثو السعادة أن الدخل الإضافي لم يعد يؤدي تقريبًا إلى مزيد من الرضا بعد مستوى معيّن."],["Wichtiger seien soziale Beziehungen, Gesundheit und das Gefühl, ein sinnvolles Leben zu führen.","فالأهم في رأيهم العلاقات الاجتماعية والصحة والشعور بأن المرء يعيش حياة ذات معنى."],["Hinzu kommt, dass unbegrenztes Wachstum auf einem Planeten mit begrenzten Ressourcen kaum möglich ist.","يضاف إلى ذلك أن النمو غير المحدود يكاد يكون مستحيلًا على كوكب محدود الموارد."],["Vertreter der Postwachstumsökonomie plädieren daher für einen bewussten Verzicht auf materiellen Konsum.","لذلك يدعو أنصار اقتصاد ما بعد النمو إلى التخلي الواعي عن الاستهلاك المادي."],["Kritiker wenden ein, dass gerade ärmere Länder auf Wachstum angewiesen seien, um Armut zu überwinden.","ويعترض المنتقدون بأن البلدان الأفقر بالذات تحتاج إلى النمو للتغلب على الفقر."],["Auch in Industrieländern ließen sich Sozialstaat und Renten ohne Wachstum nur schwer finanzieren.","وحتى في البلدان الصناعية يصعب تمويل دولة الرعاية والمعاشات دون نمو."],["Ein Mittelweg könnte darin bestehen, Wachstum vom Ressourcenverbrauch zu entkoppeln.","وقد يتمثل الطريق الوسط في فصل النمو عن استهلاك الموارد."],["Ob dies in ausreichendem Maße gelingt, ist unter Ökonomen allerdings umstritten.","غير أن نجاح ذلك بالقدر الكافي محل خلاف بين الاقتصاديين."],["Einig sind sich viele zumindest darin, dass neben dem Bruttoinlandsprodukt weitere Indikatoren für Wohlstand nötig sind.","لكن كثيرين يتفقون على الأقل على الحاجة إلى مؤشرات أخرى للرخاء إلى جانب الناتج المحلي الإجمالي."],["Ein gutes Leben bemisst sich letztlich nicht allein an dem, was wir besitzen.","فالحياة الطيبة لا تُقاس في النهاية بما نملكه وحده."]]},{"t":"ثقافة الذاكرة","de":"Erinnerungskultur","s":[["Kaum ein Land hat sich so intensiv mit seiner Vergangenheit auseinandergesetzt wie Deutschland.","يكاد لا يوجد بلد واجه ماضيه بالعمق الذي واجهته به ألمانيا."],["Gedenkstätten, Museen und die sogenannten Stolpersteine erinnern an die Verbrechen des Nationalsozialismus.","فالنصب التذكارية والمتاحف وما يُسمّى أحجار العثرة تذكّر بجرائم النازية."],["Diese Erinnerungskultur wird international häufig als vorbildlich betrachtet.","وكثيرًا ما يُنظر دوليًا إلى ثقافة الذاكرة هذه بوصفها نموذجًا يُحتذى."],["Mit dem Tod der letzten Zeitzeugen steht sie jedoch vor einem Wendepunkt.","غير أنها تقف مع رحيل آخر شهود العصر أمام نقطة تحوّل."],["Persönliche Berichte, die Geschichte greifbar gemacht haben, werden künftig fehlen.","فالروايات الشخصية التي جعلت التاريخ ملموسًا ستغيب مستقبلًا."],["Pädagogen suchen daher nach neuen Wegen, um junge Menschen zu erreichen, etwa durch digitale Zeugnisse.","لذلك يبحث التربويون عن طرق جديدة للوصول إلى الشباب، مثلًا من خلال الشهادات الرقمية."],["Zudem stellt sich die Frage, wie sich Erinnerung in einer Einwanderungsgesellschaft vermitteln lässt.","كما يُطرح السؤال عن كيفية نقل الذاكرة في مجتمع هجرة."],["Viele Menschen in Deutschland haben familiäre Wurzeln in Ländern mit ganz eigenen Erinnerungen an Krieg und Gewalt.","فكثير من الناس في ألمانيا لهم جذور عائلية في بلدان لها ذكرياتها الخاصة عن الحرب والعنف."],["Eine lebendige Erinnerungskultur sollte diese Erfahrungen nicht ausblenden, sondern in Beziehung setzen.","وينبغي لثقافة ذاكرة حية ألا تتجاهل هذه التجارب، بل أن تربط بينها."],["Gleichzeitig darf die Einzigartigkeit bestimmter Verbrechen nicht relativiert werden.","وفي الوقت نفسه لا يجوز التهوين من فرادة جرائم بعينها."],["Erinnern ist dabei kein Selbstzweck, sondern dient der Wachsamkeit gegenüber heutigen Formen der Ausgrenzung.","والتذكّر هنا ليس غاية في ذاته، بل يخدم اليقظة تجاه أشكال الإقصاء في الحاضر."],["Wer die Vergangenheit vergisst, so heißt es oft, ist dazu verurteilt, sie zu wiederholen.","وكما يُقال كثيرًا: من ينسى الماضي محكوم عليه بأن يكرره."]]},{"t":"الحرية والأمن","de":"Freiheit und Sicherheit","s":[["Das Spannungsverhältnis zwischen Freiheit und Sicherheit gehört zu den Grundfragen jedes demokratischen Staates.","تُعد العلاقة المتوترة بين الحرية والأمن من الأسئلة الجوهرية لكل دولة ديمقراطية."],["Nach terroristischen Anschlägen werden regelmäßig Forderungen nach mehr Überwachung laut.","فبعد الهجمات الإرهابية تتعالى بانتظام المطالبات بمزيد من المراقبة."],["Videokameras an öffentlichen Plätzen oder die Speicherung von Verbindungsdaten sollen Täter abschrecken und Ermittlungen erleichtern.","فالكاميرات في الأماكن العامة أو تخزين بيانات الاتصالات يُفترض أن تردع الجناة وتسهّل التحقيقات."],["Kritiker geben jedoch zu bedenken, dass der Nutzen solcher Maßnahmen oft überschätzt wird.","غير أن المنتقدين ينبّهون إلى أن فائدة هذه الإجراءات كثيرًا ما يُبالغ في تقديرها."],["Zugleich greifen sie in die Privatsphäre aller Bürger ein, auch der unbescholtenen.","وفي الوقت نفسه فإنها تتدخل في خصوصية جميع المواطنين، بمن فيهم الأبرياء."],["Bereits das Bewusstsein, beobachtet zu werden, kann Menschen davon abhalten, ihre Meinung frei zu äußern.","فمجرد الإحساس بالمراقبة قد يمنع الناس من التعبير عن آرائهم بحرية."],["Der Philosoph Benjamin Franklin soll gesagt haben, wer Freiheit für Sicherheit aufgebe, verdiene keines von beiden.","ويُنسب إلى الفيلسوف بنجامين فرانكلين قوله إن من يتخلى عن الحرية مقابل الأمن لا يستحق أيًا منهما."],["Absolute Sicherheit ist ohnehin eine Illusion, die nur um den Preis totaler Kontrolle zu haben wäre.","فالأمن المطلق على أي حال وهم لا يمكن نيله إلا بثمن السيطرة الشاملة."],["Andererseits ist ein Mindestmaß an Sicherheit selbst eine Voraussetzung für die Ausübung von Freiheit.","ومن ناحية أخرى فإن حدًا أدنى من الأمن هو نفسه شرط لممارسة الحرية."],["Wer sich auf der Straße nicht sicher fühlt, ist in seiner Bewegungsfreiheit ebenfalls eingeschränkt.","فمن لا يشعر بالأمان في الشارع تكون حرية تنقله مقيدة أيضًا."],["Es kommt daher auf die Verhältnismäßigkeit der Mittel und auf wirksame Kontrollen staatlicher Macht an.","لذلك يتوقف الأمر على تناسب الوسائل وعلى رقابة فعالة على سلطة الدولة."],["Eine wehrhafte Demokratie schützt ihre Bürger, ohne dabei ihre eigenen Werte preiszugeben.","فالديمقراطية القادرة على الدفاع عن نفسها تحمي مواطنيها دون أن تتخلى عن قيمها."]]}]};
